-- Source: 0010_onboarding.sql
-- Private setup drafts are separate from kinra_v2_profiles shared with connected coaches.
CREATE FUNCTION public.kinra_v2_kinra_valid_onboarding(v jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$
BEGIN
  IF jsonb_typeof(v) IS DISTINCT FROM 'object' OR NOT (v ?& ARRAY['role','display_name','goal','first_action','theme','language','timezone']) THEN RETURN false; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(v) k WHERE k NOT IN ('role','display_name','goal','first_action','theme','language','timezone')) THEN RETURN false; END IF;
  IF jsonb_typeof(v->'display_name') IS DISTINCT FROM 'string' OR length(v->>'display_name')>80 OR jsonb_typeof(v->'goal') IS DISTINCT FROM 'string' OR length(v->>'goal')>160 THEN RETURN false; END IF;
  IF jsonb_typeof(v->'theme') IS DISTINCT FROM 'string' OR v->>'theme' NOT IN ('dark','light','system') OR jsonb_typeof(v->'language') IS DISTINCT FROM 'string' OR v->>'language' NOT IN ('en','bs','de') THEN RETURN false; END IF;
  IF jsonb_typeof(v->'timezone') IS DISTINCT FROM 'string' OR (v->>'timezone') !~ '^[A-Za-z0-9_+/-]{1,80}$' THEN RETURN false; END IF;
  IF v->'role' <> 'null'::jsonb AND (jsonb_typeof(v->'role') <> 'string' OR v->>'role' NOT IN ('solo','client','trainer')) THEN RETURN false; END IF;
  IF v->'first_action' <> 'null'::jsonb AND (jsonb_typeof(v->'first_action') <> 'string' OR v->>'first_action' NOT IN ('workout','food','sleep','connect','plan','overview','program','clients','dashboard')) THEN RETURN false; END IF;
  IF v->>'first_action' IS NOT NULL AND NOT coalesce(CASE v->>'role' WHEN 'solo' THEN v->>'first_action' IN ('workout','food','sleep') WHEN 'client' THEN v->>'first_action' IN ('connect','plan','overview') WHEN 'trainer' THEN v->>'first_action' IN ('program','clients','dashboard') ELSE false END,false) THEN RETURN false; END IF;
  RETURN true;
END $$;
REVOKE ALL ON FUNCTION public.kinra_v2_kinra_valid_onboarding(jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.kinra_v2_kinra_valid_onboarding(jsonb) TO authenticated,service_role;

CREATE TABLE public.kinra_v2_onboarding_state (
  owner_id uuid PRIMARY KEY REFERENCES public.kinra_v2_profiles(id) ON DELETE CASCADE DEFAULT auth.uid(),
  version integer NOT NULL DEFAULT 1 CHECK(version=1),
  step integer NOT NULL DEFAULT 0 CHECK(step BETWEEN 0 AND 3),
  answers jsonb NOT NULL CHECK(public.kinra_v2_kinra_valid_onboarding(answers)),
  completed_at timestamptz,
  updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.kinra_v2_onboarding_state ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.kinra_v2_onboarding_state FROM PUBLIC,anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.kinra_v2_onboarding_state TO authenticated;
GRANT ALL ON public.kinra_v2_onboarding_state TO service_role;
CREATE POLICY "Kinra v2: Read own setup" ON public.kinra_v2_onboarding_state FOR SELECT TO authenticated USING(owner_id=(SELECT auth.uid()));
CREATE POLICY "Kinra v2: Create own setup" ON public.kinra_v2_onboarding_state FOR INSERT TO authenticated WITH CHECK(owner_id=(SELECT auth.uid()));
CREATE POLICY "Kinra v2: Change own setup" ON public.kinra_v2_onboarding_state FOR UPDATE TO authenticated USING(owner_id=(SELECT auth.uid())) WITH CHECK(owner_id=(SELECT auth.uid()));
CREATE POLICY "Kinra v2: Delete own setup" ON public.kinra_v2_onboarding_state FOR DELETE TO authenticated USING(owner_id=(SELECT auth.uid()));

-- Invoker privileges retain every normal profile/role/preference RLS check.
-- One transaction commits setup, profile, role and appearance; retries are safe.
CREATE FUNCTION public.kinra_v2_kinra_save_onboarding(data jsonb,stage integer,finish boolean,expected_owner uuid) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE actor uuid:=auth.uid(); chosen public.kinra_v2_app_role; existing public.kinra_v2_app_role;
BEGIN
  IF actor IS NULL OR actor IS DISTINCT FROM expected_owner THEN RAISE EXCEPTION 'Your account changed. Reopen this screen before saving.' USING ERRCODE='42501'; END IF;
  IF stage IS NULL OR finish IS NULL OR stage NOT BETWEEN 0 AND 3 OR NOT public.kinra_v2_kinra_valid_onboarding(data) THEN RAISE EXCEPTION 'Enter valid setup details.' USING ERRCODE='22023'; END IF;
  IF finish AND (nullif(trim(data->>'display_name'),'') IS NULL OR data->>'role' IS NULL OR data->>'first_action' IS NULL) THEN RAISE EXCEPTION 'Complete the required setup steps.' USING ERRCODE='22023'; END IF;
  INSERT INTO public.kinra_v2_profiles(id) VALUES(actor) ON CONFLICT(id) DO NOTHING;
  INSERT INTO public.kinra_v2_onboarding_state(owner_id,answers,step) VALUES(actor,data,stage) ON CONFLICT(owner_id) DO NOTHING;
  PERFORM 1 FROM public.kinra_v2_onboarding_state WHERE owner_id=actor FOR UPDATE;
  SELECT role INTO existing FROM public.kinra_v2_user_roles WHERE user_id=actor;
  IF existing IS NOT NULL AND existing::text IS DISTINCT FROM data->>'role' THEN RAISE EXCEPTION 'Your account type is already set. Reopen setup to continue.' USING ERRCODE='22023'; END IF;
  IF finish THEN
    chosen:=(data->>'role')::public.kinra_v2_app_role;
    INSERT INTO public.kinra_v2_user_roles(user_id,role) VALUES(actor,chosen) ON CONFLICT(user_id) DO NOTHING;
    IF NOT EXISTS(SELECT 1 FROM public.kinra_v2_user_roles WHERE user_id=actor AND role=chosen) THEN RAISE EXCEPTION 'Your account type is already set. Reopen setup to continue.' USING ERRCODE='22023'; END IF;
    UPDATE public.kinra_v2_profiles SET display_name=trim(data->>'display_name'),goal=nullif(trim(data->>'goal'),'') WHERE id=actor;
    INSERT INTO public.kinra_v2_feature_records(owner_id,kind,payload) VALUES(actor,'preferences',jsonb_build_object('language',data->>'language','theme',data->>'theme','modules','{}'::jsonb,'timezone',data->>'timezone'))
      ON CONFLICT(owner_id,kind,dedupe_key) DO UPDATE SET payload=public.kinra_v2_feature_records.payload || jsonb_build_object('language',data->>'language','theme',data->>'theme');
  END IF;
  UPDATE public.kinra_v2_onboarding_state SET answers=data,step=CASE WHEN finish THEN 3 ELSE stage END,updated_at=now(),completed_at=CASE WHEN finish THEN coalesce(completed_at,now()) ELSE NULL END WHERE owner_id=actor;
END $$;
REVOKE ALL ON FUNCTION public.kinra_v2_kinra_save_onboarding(jsonb,integer,boolean,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.kinra_v2_kinra_save_onboarding(jsonb,integer,boolean,uuid) TO authenticated,service_role;


-- Source: 0011_onboarding_measurements.sql
-- Optional setup facts stay in the owner-only setup row, never coach-visible logs.
ALTER TABLE public.kinra_v2_onboarding_state DROP CONSTRAINT kinra_v2_onboarding_state_version_check;
ALTER TABLE public.kinra_v2_onboarding_state ADD CONSTRAINT kinra_v2_onboarding_state_version_check CHECK(version IN (1,2));
ALTER TABLE public.kinra_v2_onboarding_state ALTER COLUMN version SET DEFAULT 2;
ALTER TABLE public.kinra_v2_onboarding_state DROP CONSTRAINT kinra_v2_onboarding_state_step_check;
ALTER TABLE public.kinra_v2_onboarding_state ADD CONSTRAINT kinra_v2_onboarding_state_step_check CHECK(step BETWEEN 0 AND 4);

CREATE OR REPLACE FUNCTION public.kinra_v2_kinra_valid_onboarding(v jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$
BEGIN
  IF jsonb_typeof(v) IS DISTINCT FROM 'object' OR NOT (v ?& ARRAY['role','display_name','goal','first_action','theme','language','timezone']) THEN RETURN false; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(v) k WHERE k NOT IN ('role','display_name','goal','first_action','theme','language','timezone','gender','height_cm','weight_kg','units','experience')) THEN RETURN false; END IF;
  IF jsonb_typeof(v->'display_name') IS DISTINCT FROM 'string' OR length(v->>'display_name')>80 OR jsonb_typeof(v->'goal') IS DISTINCT FROM 'string' OR length(v->>'goal')>160 THEN RETURN false; END IF;
  IF jsonb_typeof(v->'theme') IS DISTINCT FROM 'string' OR v->>'theme' NOT IN ('dark','light','system') OR jsonb_typeof(v->'language') IS DISTINCT FROM 'string' OR v->>'language' NOT IN ('en','bs','de') THEN RETURN false; END IF;
  IF jsonb_typeof(v->'timezone') IS DISTINCT FROM 'string' OR (v->>'timezone') !~ '^[A-Za-z0-9_+/-]{1,80}$' THEN RETURN false; END IF;
  IF v->'role' <> 'null'::jsonb AND (jsonb_typeof(v->'role') <> 'string' OR v->>'role' NOT IN ('solo','client','trainer')) THEN RETURN false; END IF;
  IF v->'first_action' <> 'null'::jsonb AND (jsonb_typeof(v->'first_action') <> 'string' OR v->>'first_action' NOT IN ('workout','food','sleep','connect','plan','overview','program','clients','dashboard')) THEN RETURN false; END IF;
  IF v->>'first_action' IS NOT NULL AND NOT coalesce(CASE v->>'role' WHEN 'solo' THEN v->>'first_action' IN ('workout','food','sleep') WHEN 'client' THEN v->>'first_action' IN ('connect','plan','overview') WHEN 'trainer' THEN v->>'first_action' IN ('program','clients','dashboard') ELSE false END,false) THEN RETURN false; END IF;
  IF v ? 'gender' AND v->'gender' <> 'null'::jsonb AND (jsonb_typeof(v->'gender') <> 'string' OR v->>'gender' NOT IN ('woman','man','non_binary','another_identity','prefer_not_to_say')) THEN RETURN false; END IF;
  IF v ? 'experience' AND v->'experience' <> 'null'::jsonb AND (jsonb_typeof(v->'experience') <> 'string' OR v->>'experience' NOT IN ('new','some','experienced')) THEN RETURN false; END IF;
  IF v ? 'units' AND (jsonb_typeof(v->'units') IS DISTINCT FROM 'string' OR v->>'units' NOT IN ('metric','imperial')) THEN RETURN false; END IF;
  IF v ? 'height_cm' AND v->'height_cm' <> 'null'::jsonb THEN
    IF jsonb_typeof(v->'height_cm') <> 'number' THEN RETURN false; END IF;
    IF (v->>'height_cm')::numeric NOT BETWEEN 80 AND 250 THEN RETURN false; END IF;
  END IF;
  IF v ? 'weight_kg' AND v->'weight_kg' <> 'null'::jsonb THEN
    IF jsonb_typeof(v->'weight_kg') <> 'number' THEN RETURN false; END IF;
    IF (v->>'weight_kg')::numeric NOT BETWEEN 20 AND 350 THEN RETURN false; END IF;
  END IF;
  RETURN true;
END $$;

CREATE OR REPLACE FUNCTION public.kinra_v2_kinra_save_onboarding(data jsonb,stage integer,finish boolean,expected_owner uuid) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE actor uuid:=auth.uid(); chosen public.kinra_v2_app_role; existing public.kinra_v2_app_role; prior jsonb; modern boolean; next_stage integer; merged jsonb;
BEGIN
  IF actor IS NULL OR actor IS DISTINCT FROM expected_owner THEN RAISE EXCEPTION 'Your account changed. Reopen this screen before saving.' USING ERRCODE='42501'; END IF;
  modern := data ? 'height_cm';
  IF stage IS NULL OR finish IS NULL OR stage NOT BETWEEN 0 AND (CASE WHEN modern THEN 4 ELSE 3 END) OR NOT public.kinra_v2_kinra_valid_onboarding(data) THEN RAISE EXCEPTION 'Enter valid setup details.' USING ERRCODE='22023'; END IF;
  IF finish AND (nullif(trim(data->>'display_name'),'') IS NULL OR data->>'role' IS NULL OR data->>'first_action' IS NULL) THEN RAISE EXCEPTION 'Complete the required setup steps.' USING ERRCODE='22023'; END IF;
  INSERT INTO public.kinra_v2_profiles(id) VALUES(actor) ON CONFLICT(id) DO NOTHING;
  INSERT INTO public.kinra_v2_onboarding_state(owner_id,answers,step) VALUES(actor,data,stage) ON CONFLICT(owner_id) DO NOTHING;
  SELECT answers INTO prior FROM public.kinra_v2_onboarding_state WHERE owner_id=actor FOR UPDATE;
  SELECT role INTO existing FROM public.kinra_v2_user_roles WHERE user_id=actor;
  IF existing IS NOT NULL AND existing::text IS DISTINCT FROM data->>'role' THEN RAISE EXCEPTION 'Your account type is already set. Reopen setup to continue.' USING ERRCODE='22023'; END IF;
  -- A cached four-step client must not erase facts saved by the new setup.
  merged := coalesce(prior,'{}'::jsonb) || data;
  next_stage := CASE WHEN NOT modern AND stage>=2 THEN stage+1 ELSE stage END;
  IF finish THEN
    chosen:=(data->>'role')::public.kinra_v2_app_role;
    INSERT INTO public.kinra_v2_user_roles(user_id,role) VALUES(actor,chosen) ON CONFLICT(user_id) DO NOTHING;
    IF NOT EXISTS(SELECT 1 FROM public.kinra_v2_user_roles WHERE user_id=actor AND role=chosen) THEN RAISE EXCEPTION 'Your account type is already set. Reopen setup to continue.' USING ERRCODE='22023'; END IF;
    UPDATE public.kinra_v2_profiles SET display_name=trim(data->>'display_name'),goal=nullif(trim(data->>'goal'),'') WHERE id=actor;
    INSERT INTO public.kinra_v2_feature_records(owner_id,kind,payload) VALUES(actor,'preferences',jsonb_build_object('language',data->>'language','theme',data->>'theme','modules','{}'::jsonb,'timezone',data->>'timezone') || CASE WHEN data ? 'units' THEN jsonb_build_object('units',data->>'units') ELSE '{}'::jsonb END)
      ON CONFLICT(owner_id,kind,dedupe_key) DO UPDATE SET payload=public.kinra_v2_feature_records.payload || jsonb_build_object('language',data->>'language','theme',data->>'theme') || CASE WHEN data ? 'units' THEN jsonb_build_object('units',data->>'units') ELSE '{}'::jsonb END;
  END IF;
  UPDATE public.kinra_v2_onboarding_state SET answers=merged,version=2,step=CASE WHEN finish THEN 4 ELSE next_stage END,updated_at=now(),completed_at=CASE WHEN finish THEN coalesce(completed_at,now()) ELSE NULL END WHERE owner_id=actor;
END $$;
REVOKE ALL ON FUNCTION public.kinra_v2_kinra_valid_onboarding(jsonb),public.kinra_v2_kinra_save_onboarding(jsonb,integer,boolean,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.kinra_v2_kinra_valid_onboarding(jsonb),public.kinra_v2_kinra_save_onboarding(jsonb,integer,boolean,uuid) TO authenticated,service_role;


-- Source: 0012_usable_templates.sql
-- Every account can own private training plans; assignment still requires a
-- real coach/client relationship under the existing assignment policies.
DROP POLICY "Kinra v2: trainer owns" ON public.kinra_v2_programs;
CREATE POLICY "Kinra v2: Own personal kinra_v2_programs" ON public.kinra_v2_programs FOR ALL TO authenticated
  USING(trainer_id=(SELECT auth.uid())) WITH CHECK(trainer_id=(SELECT auth.uid()));

CREATE TABLE public.kinra_v2_template_catalogue (
  id text PRIMARY KEY CHECK(length(id) BETWEEN 1 AND 120),
  kind text NOT NULL CHECK(kind IN ('training','nutrition')),
  content_version integer NOT NULL DEFAULT 1 CHECK(content_version>0),
  payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object' AND payload ?& ARRAY['en','bs','de']),
  updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.kinra_v2_template_catalogue ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.kinra_v2_template_catalogue FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.kinra_v2_template_catalogue TO authenticated;
GRANT ALL ON public.kinra_v2_template_catalogue TO service_role;
CREATE POLICY "Kinra v2: Read published templates" ON public.kinra_v2_template_catalogue FOR SELECT TO authenticated USING(true);

CREATE TABLE public.kinra_v2_template_adoptions (
  owner_id uuid NOT NULL DEFAULT auth.uid() REFERENCES public.kinra_v2_profiles(id) ON DELETE CASCADE,
  template_id text NOT NULL REFERENCES public.kinra_v2_template_catalogue(id),
  kind text NOT NULL CHECK(kind IN ('training','nutrition')),
  content_version integer NOT NULL,
  program_id uuid REFERENCES public.kinra_v2_programs(id) ON DELETE SET NULL,
  feature_id uuid REFERENCES public.kinra_v2_feature_records(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY(owner_id,template_id),
  CHECK((kind='training' AND feature_id IS NULL) OR (kind='nutrition' AND program_id IS NULL))
);
CREATE INDEX kinra_v2_template_adoptions_program_idx ON public.kinra_v2_template_adoptions(program_id) WHERE program_id IS NOT NULL;
CREATE INDEX kinra_v2_template_adoptions_feature_idx ON public.kinra_v2_template_adoptions(feature_id) WHERE feature_id IS NOT NULL;
ALTER TABLE public.kinra_v2_template_adoptions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.kinra_v2_template_adoptions FROM PUBLIC,anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.kinra_v2_template_adoptions TO authenticated;
GRANT ALL ON public.kinra_v2_template_adoptions TO service_role;
CREATE POLICY "Kinra v2: Own template copies" ON public.kinra_v2_template_adoptions FOR ALL TO authenticated
  USING(owner_id=(SELECT auth.uid())) WITH CHECK(owner_id=(SELECT auth.uid())
    AND EXISTS(SELECT 1 FROM public.kinra_v2_template_catalogue t WHERE t.id=kinra_v2_template_adoptions.template_id AND t.kind=kinra_v2_template_adoptions.kind)
    AND (program_id IS NULL OR EXISTS(SELECT 1 FROM public.kinra_v2_programs p WHERE p.id=program_id AND p.trainer_id=(SELECT auth.uid())))
    AND (feature_id IS NULL OR EXISTS(SELECT 1 FROM public.kinra_v2_feature_records f WHERE f.id=feature_id AND f.owner_id=(SELECT auth.uid()) AND f.kind='nutrition_plan' AND f.client_id IS NULL AND f.visibility='private')));

CREATE FUNCTION public.kinra_v2_kinra_adopt_template(template_key text,locale text,expected_owner uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE actor uuid:=auth.uid(); source public.kinra_v2_template_catalogue; receipt public.kinra_v2_template_adoptions; data jsonb; target uuid;
BEGIN
  IF actor IS NULL OR actor IS DISTINCT FROM expected_owner THEN RAISE EXCEPTION 'Your account changed. Reopen this screen before saving.' USING ERRCODE='42501'; END IF;
  IF locale IS NULL OR locale NOT IN ('en','bs','de') THEN RAISE EXCEPTION 'Choose a supported language.' USING ERRCODE='22023'; END IF;
  SELECT * INTO source FROM public.kinra_v2_template_catalogue WHERE id=template_key;
  IF NOT FOUND THEN RAISE EXCEPTION 'This template is no longer available.' USING ERRCODE='22023'; END IF;
  INSERT INTO public.kinra_v2_template_adoptions(owner_id,template_id,kind,content_version) VALUES(actor,source.id,source.kind,source.content_version)
    ON CONFLICT(owner_id,template_id) DO NOTHING;
  SELECT * INTO receipt FROM public.kinra_v2_template_adoptions WHERE owner_id=actor AND template_id=source.id FOR UPDATE;
  target:=coalesce(receipt.program_id,receipt.feature_id);
  IF target IS NOT NULL THEN
    RETURN jsonb_build_object('id',target,'kind',source.kind,'alreadySaved',true);
  END IF;
  data:=source.payload->locale;
  target:=gen_random_uuid();
  IF source.kind='training' THEN
    INSERT INTO public.kinra_v2_programs(id,trainer_id,name,description,weeks,days) VALUES(target,actor,data->>'name',data->>'description',(data->>'weeks')::integer,data->'days');
    UPDATE public.kinra_v2_template_adoptions SET program_id=target,content_version=source.content_version WHERE owner_id=actor AND template_id=source.id;
  ELSE
    INSERT INTO public.kinra_v2_feature_records(id,owner_id,kind,payload,visibility) VALUES(target,actor,'nutrition_plan',data,'private');
    UPDATE public.kinra_v2_template_adoptions SET feature_id=target,content_version=source.content_version WHERE owner_id=actor AND template_id=source.id;
  END IF;
  RETURN jsonb_build_object('id',target,'kind',source.kind,'alreadySaved',false);
END $$;
REVOKE ALL ON FUNCTION public.kinra_v2_kinra_adopt_template(text,text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.kinra_v2_kinra_adopt_template(text,text,uuid) TO authenticated,service_role;


