('kinra-muscle-four','training',1,'{"en":{"name":"Muscle building · 4 days","description":"A four-day upper/lower example with additional chest, back and leg work. Use upper, lower, rest, upper, lower.\n\nRepeat the listed week. Begin at the low end of each rep range with 3–4 reps in reserve (RPE 6–7). Add one rep per set when controlled; after every set reaches the top, increase the smallest available load and return to the low end. Do not increase load and sets together. If recovery or form worsens, repeat the previous week or remove one set.\n\nAn original general adult example, not an individually assessed prescription. Review exercises and equipment first. Start with easy practice sets; stop for pain or feeling unwell. Schedule rest between hard sessions. Adjust or seek qualified guidance when health, pregnancy or injury affects exercise.","weeks":8,"days":[{"title":"A · Upper","exercises":[{"catalogue_id":"exercise-0060-bench-press-potisak-s-ravne-klupe","name":"Bench Press (Potisak s ravne klupe)","sets":3,"reps":"6–10","rest_seconds":150,"rpe":7,"section":"main","notes":"Use a rack with correctly set safeties or a competent spotter where needed. Warm up with lighter practice sets before the working sets."},{"catalogue_id":"exercise-0574-seated-cable-row-veslanje-na-sajli-sjedece","name":"Seated Cable Row (Veslanje na sajli — sjedeće)","sets":3,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0233-dumbbell-shoulder-press-sjedeci-potisak-bucicama","name":"Dumbbell Shoulder Press (Sjedeći potisak bučicama)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0377-lat-pulldown-povlacenje-na-lat-masini","name":"Lat Pulldown (Povlačenje na lat mašini)","sets":2,"reps":"8–12","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0227-dumbbell-lateral-raise","name":"Dumbbell Lateral Raise","sets":2,"reps":"12–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0554-rope-triceps-pushdown","name":"Rope Triceps Pushdown","sets":2,"reps":"10–15","rest_seconds":60,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0266-flat-machine-chest-press-wide-grip","name":"Flat Machine Chest Press (Wide Grip)","sets":2,"reps":"10–15","rest_seconds":90,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."}]},{"title":"A · Lower","exercises":[{"catalogue_id":"exercise-0035-back-squat-cucanj-sa-sipkom","name":"Back Squat (Čučanj sa šipkom)","sets":3,"reps":"6–10","rest_seconds":180,"rpe":7,"section":"main","notes":"Use a rack with correctly set safeties or a competent spotter where needed. Warm up with lighter practice sets before the working sets."},{"catalogue_id":"exercise-0549-romanian-deadlift","name":"Romanian Deadlift","sets":3,"reps":"8–10","rest_seconds":150,"rpe":7,"section":"main","notes":"Use a rack with correctly set safeties or a competent spotter where needed. Warm up with lighter practice sets before the working sets."},{"catalogue_id":"exercise-0392-leg-extension-machine","name":"Leg Extension (Machine)","sets":2,"reps":"10–15","rest_seconds":75,"rpe":7,"section":"main","notes":"Use a controlled range and steady breathing. Choose a load that leaves the stated effort in reserve."},{"catalogue_id":"exercise-0575-seated-calf-raise","name":"Seated Calf Raise","sets":3,"reps":"10–15","rest_second