-- Source: 0014_account_workspaces.sql
CREATE TABLE public.kinra_v2_account_roles (
 owner_id uuid NOT NULL DEFAULT auth.uid() REFERENCES public.kinra_v2_profiles(id) ON DELETE CASCADE,
 role text NOT NULL CHECK(role IN ('solo','client','trainer','specialist','organization')),
 created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(owner_id,role)
);
CREATE TABLE public.kinra_v2_account_context (
 owner_id uuid PRIMARY KEY DEFAULT auth.uid() REFERENCES public.kinra_v2_profiles(id) ON DELETE CASCADE,
 active_role text NOT NULL,
 FOREIGN KEY(owner_id,active_role) REFERENCES public.kinra_v2_account_roles(owner_id,role)
);
ALTER TABLE public.kinra_v2_account_roles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.kinra_v2_account_context ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.kinra_v2_account_roles,public.kinra_v2_account_context FROM PUBLIC,anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.kinra_v2_account_roles,public.kinra_v2_account_context TO authenticated;
GRANT ALL ON public.kinra_v2_account_roles,public.kinra_v2_account_context TO service_role;
CREATE POLICY "Kinra v2: Own workspace roles" ON public.kinra_v2_account_roles FOR ALL TO authenticated USING(owner_id=(SELECT auth.uid())) WITH CHECK(owner_id=(SELECT auth.uid()));
CREATE POLICY "Kinra v2: Own active workspace" ON public.kinra_v2_account_context FOR ALL TO authenticated USING(owner_id=(SELECT auth.uid())) WITH CHECK(owner_id=(SELECT auth.uid()));

-- Preserve the existing narrow definer boolean helper, including private role
-- membership lookup needed when a client checks a coach's public code.
CREATE OR REPLACE FUNCTION public.kinra_v2_has_role(_user_id uuid,_role public.kinra_v2_app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT EXISTS(SELECT 1 FROM public.kinra_v2_user_roles WHERE user_id=_user_id AND role=_role)
 OR EXISTS(SELECT 1 FROM public.kinra_v2_account_roles WHERE owner_id=_user_id AND (role=_role::text OR (_role::text='trainer' AND role='specialist')))
$$;
REVOKE ALL ON FUNCTION public.kinra_v2_has_role(uuid,public.kinra_v2_app_role) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.kinra_v2_has_role(uuid,public.kinra_v2_app_role) TO authenticated,service_role;

CREATE FUNCTION public.kinra_v2_kinra_account_workspaces(expected_owner uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE actor uuid:=auth.uid(); original text; active text; available jsonb;
BEGIN
 IF actor IS NULL OR actor IS DISTINCT FROM expected_owner THEN RAISE EXCEPTION 'Your account changed. Reopen this screen before saving.' USING ERRCODE='42501'; END IF;
 SELECT role::text INTO original FROM public.kinra_v2_user_roles WHERE user_id=actor;
 SELECT active_role INTO active FROM public.kinra_v2_account_context WHERE owner_id=actor;
 SELECT coalesce(jsonb_agg(role ORDER BY role),'[]'::jsonb) INTO available FROM (SELECT role FROM public.kinra_v2_account_roles WHERE owner_id=actor UNION SELECT original WHERE original IS NOT NULL) q;
 RETURN jsonb_build_object('active',coalesce(active,original),'primary',original,'roles',available);
END $$;
CREATE FUNCTION public.kinra_v2_kinra_set_workspace(workspace text,add_role boolean,expected_owner uuid) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE actor uuid:=auth.uid(); original text;
BEGIN
 IF actor IS NULL OR actor IS DISTINCT FROM expected_owner THEN RAISE EXCEPTION 'Your account changed. Reopen this screen before saving.' USING ERRCODE='42501'; END IF;
 IF workspace IS NULL OR workspace NOT IN ('solo','client','trainer','specialist','organization') OR add_role IS NULL THEN RAISE EXCEPTION 'Choose a supported workspace.' USING ERRCODE='22023'; END IF;
 SELECT role::text INTO original FROM public.kinra_v2_user_roles WHERE user_id=actor;
 IF original IS NULL THEN RAISE EXCEPTION 'Complete your account setup first.' USING ERRCODE='22023'; END IF;
 INSERT INTO public.kinra_v2_account_roles(owner_id,role) VALUES(actor,original) ON CONFLICT DO NOTHING;
 IF add_role THEN INSERT INTO public.kinra_v2_account_roles(owner_id,role) VALUES(actor,workspace) ON CONFLICT DO NOTHING; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.kinra_v2_account_roles WHERE owner_id=actor AND role=workspace) THEN RAISE EXCEPTION 'Add this workspace before switching to it.' USING ERRCODE='42501'; END IF;
 INSERT INTO public.kinra_v2_account_context(owner_id,active_role) VALUES(actor,workspace) ON CONFLICT(owner_id) DO UPDATE SET active_role=excluded.active_role;
END $$;
REVOKE ALL ON FUNCTION public.kinra_v2_kinra_account_workspaces(uuid),public.kinra_v2_kinra_set_workspace(text,boolean,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.kinra_v2_kinra_account_workspaces(uuid),public.kinra_v2_kinra_set_workspace(text,boolean,uuid) TO authenticated,service_role;


-- Source: 0015_optional_questionnaire.sql
-- Additional optional questionnaire answers remain owner-only.
CREATE OR REPLACE FUNCTION public.kinra_v2_kinra_valid_onboarding(v jsonb) RETURNS boolean LANGUAGE plpgsql STABLE SET search_path='' AS $$
BEGIN
  IF jsonb_typeof(v) IS DISTINCT FROM 'object' OR NOT (v ?& ARRAY['role','display_name','goal','first_action','theme','language','timezone']) THEN RETURN false; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(v) k WHERE k NOT IN ('role','display_name','goal','first_action','theme','language','timezone','gender','height_cm','weight_kg','units','experience','birth_date','activity_level','city','limitations')) THEN RETURN false; END IF;
  IF jsonb_typeof(v->'display_name') IS DISTINCT FROM 'string' OR length(v->>'display_name')>80 OR jsonb_typeof(v->'goal') IS DISTINCT FROM 'string' OR length(v->>'goal')>160 THEN RETURN false; END IF;
  IF jsonb_typeof(v->'theme') IS DISTINCT FROM 'string' OR v->>'theme' NOT IN ('dark','light','system') OR jsonb_typeof(v->'language') IS DISTINCT FROM 'string' OR v->>'language' NOT IN ('en','bs','de') THEN RETURN false; END IF;
  IF jsonb_typeof(v->'timezone') IS DISTINCT FROM 'string' OR (v->>'timezone') !~ '^[A-Za-z0-9_+/-]{1,80}$' THEN RETURN false; END IF;
  IF v->'role' <> 'null'::jsonb AND (jsonb_typeof(v->'role') <> 'string' OR v->>'role' NOT IN ('solo','client','trainer')) THEN RETURN false; END IF;
  IF v->'first_action' <> 'null'::jsonb AND (jsonb_typeof(v->'first_action') <> 'string' OR v->>'first_action' NOT IN ('workout','food','sleep','connect','plan','overview','program','clients','dashboard')) THEN RETURN false; END IF;
  IF v->>'first_action' IS NOT NULL AND NOT coalesce(CASE v->>'role' WHEN 'solo' THEN v->>'first_action' IN ('workout','food','sleep') WHEN 'client' THEN v->>'first_action' IN ('connect','plan','overview') WHEN 'trainer' THEN v->>'first_action' IN ('program','clients','dashboard') ELSE false END,false) THEN RETURN false; END IF;
  IF v ? 'gender' AND v->'gender' <> 'null'::jsonb AND (jsonb_typeof(v->'gender') <> 'string' OR v->>'gender' NOT IN ('woman','man','non_binary','another_identity','prefer_not_to_say')) THEN RETURN false; END IF;
  IF v ? 'experience' AND v->'experience' <> 'null'::jsonb AND (jsonb_typeof(v->'experience') <> 'string' OR v->>'experience' NOT IN ('new','some','experienced')) THEN RETURN false; END IF;
  IF v ? 'units' AND (jsonb_typeof(v->'units') IS DISTINCT FROM 'string' OR v->>'units' NOT IN ('metric','imperial')) THEN RETURN false; END IF;
  IF v ? 'height_cm' AND v->'height_cm' <> 'null'::jsonb THEN
    IF jsonb_typeof(v->'height_cm') <> 'number' THEN RETURN false; END IF;
    IF (v->>'height_cm')::numeric NOT BETWEEN 80 AND 250 THEN RETURN false; END IF;
  END IF;
  IF v ? 'weight_kg' AND v->'weight_kg' <> 'null'::jsonb THEN
    IF jsonb_typeof(v->'weight_kg') <> 'number' THEN RETURN false; END IF;
    IF (v->>'weight_kg')::numeric NOT BETWEEN 20 AND 350 THEN RETURN false; END IF;
  END IF;

  IF v ? 'birth_date' AND v->'birth_date' <> 'null'::jsonb THEN
    IF jsonb_typeof(v->'birth_date') <> 'string' OR v->>'birth_date' !~ '^\d{4}-\d{2}-\d{2}$' THEN RETURN false; END IF;
    BEGIN IF (v->>'birth_date')::date < DATE '1900-01-01' OR (v->>'birth_date')::date > CURRENT_DATE THEN RETURN false; END IF;
    EXCEPTION WHEN datetime_field_overflow OR invalid_datetime_format THEN RETURN false; END;
  END IF;
  IF v ? 'activity_level' AND v->'activity_level' <> 'null'::jsonb AND (jsonb_typeof(v->'activity_level') <> 'string' OR v->>'activity_level' NOT IN ('low','moderate','high')) THEN RETURN false; END IF;
  IF v ? 'city' AND (jsonb_typeof(v->'city') IS DISTINCT FROM 'string' OR length(v->>'city')>100) THEN RETURN false; END IF;
  IF v ? 'limitations' AND (jsonb_typeof(v->'limitations') IS DISTINCT FROM 'string' OR length(v->>'limitations')>1000) THEN RETURN false; END IF;
  RETURN true;
END $$;



-- Source: 0016_organizations_and_availability.sql
-- Organization authority is independent of account workspace selection and coach
-- connections. No organization policy grants access to health records.
CREATE TABLE public.kinra_v2_organization_staff (
 organization_id uuid NOT NULL REFERENCES public.kinra_v2_feature_records(id) ON DELETE CASCADE,
 user_id uuid NOT NULL REFERENCES public.kinra_v2_profiles(id) ON DELETE CASCADE,
 role text NOT NULL CHECK(role IN ('manager','staff')),
 created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(organization_id,user_id)
);
CREATE TABLE public.kinra_v2_organization_invites (
 code uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 organization_id uuid NOT NULL REFERENCES public.kinra_v2_feature_records(id) ON DELETE CASCADE,
 role text NOT NULL CHECK(role IN ('manager','staff')),
 created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL,
 revoked_at timestamptz, used_at timestamptz, used_by uuid REFERENCES public.kinra_v2_profiles(id) ON DELETE SET NULL,
 CHECK(expires_at>=created_at+interval '5 minutes' AND expires_at<=created_at+interval '30 days')
);
CREATE TABLE public.kinra_v2_organization_memberships (
 organization_id uuid NOT NULL REFERENCES public.kinra_v2_feature_records(id) ON DELETE CASCADE,
 user_id uuid NOT NULL REFERENCES public.kinra_v2_profiles(id) ON DELETE CASCADE,
 status text NOT NULL CHECK(status IN ('active','paused','ended')),
 start_date date NOT NULL, end_date date, plan_id uuid REFERENCES public.kinra_v2_feature_records(id) ON DELETE SET NULL,
 updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(organization_id,user_id),
 CHECK(end_date IS NULL OR end_date>=start_date)
);
-- Finance and internal bookkeeping notes are withheld from read-only staff.
CREATE TABLE public.kinra_v2_organization_membership_finance (
 organization_id uuid NOT NULL, user_id uuid NOT NULL,
 paid_amount numeric CHECK(paid_amount>=0 AND paid_amount<=1000000),
 currency text CHECK(currency IN ('EUR','USD','BAM','GBP')), notes text NOT NULL DEFAULT '' CHECK(length(notes)<=1000),
 PRIMARY KEY(organization_id,user_id),
 FOREIGN KEY(organization_id,user_id) REFERENCES public.kinra_v2_organization_memberships ON DELETE CASCADE,
 CHECK(paid_amount IS NULL OR currency IS NOT NULL)
);
ALTER TABLE public.kinra_v2_organization_staff ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.kinra_v2_organization_invites ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.kinra_v2_organization_memberships ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.kinra_v2_organization_membership_finance ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.kinra_v2_organization_staff,public.kinra_v2_organization_invites,public.kinra_v2_organization_memberships,public.kinra_v2_organization_membership_finance FROM PUBLIC,anon,authenticated;
GRANT SELECT,DELETE ON public.kinra_v2_organization_staff TO authenticated;
GRANT UPDATE(role) ON public.kinra_v2_organization_staff TO authenticated;
GRANT SELECT ON public.kinra_v2_organization_invites TO authenticated;
GRANT INSERT(organization_id,role,expires_at) ON public.kinra_v2_organization_invites TO authenticated;
GRANT UPDATE(revoked_at) ON public.kinra_v2_organization_invites TO authenticated;
GRANT SELECT,INSERT,UPDATE ON public.kinra_v2_organization_memberships,public.kinra_v2_organization_membership_finance TO authenticated;
GRANT ALL ON public.kinra_v2_organization_staff,public.kinra_v2_organization_invites,public.kinra_v2_organization_memberships,public.kinra_v2_organization_membership_finance TO service_role;

-- Narrow definer: resolve only the caller's role, avoiding recursive staff RLS
-- and permitting private organization lookup. No arbitrary-user role lookup.
CREATE FUNCTION public.kinra_v2_kinra_org_role(org_id uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT CASE WHEN o.owner_id=auth.uid() THEN 'owner' ELSE s.role END
 FROM public.kinra_v2_feature_records o LEFT JOIN public.kinra_v2_organization_staff s ON s.organization_id=o.id AND s.user_id=auth.uid()
 WHERE auth.uid() IS NOT NULL AND o.id=org_id AND o.kind='organization'
$$;
CREATE POLICY "Kinra v2: Organization staff roster" ON public.kinra_v2_organization_staff FOR SELECT TO authenticated USING(public.kinra_v2_kinra_org_role(organization_id) IS NOT NULL);
CREATE POLICY "Kinra v2: Owner changes staff role" ON public.kinra_v2_organization_staff FOR UPDATE TO authenticated USING(public.kinra_v2_kinra_org_role(organization_id)='owner') WITH CHECK(public.kinra_v2_kinra_org_role(organization_id)='owner');
CREATE POLICY "Kinra v2: Owner removes staff" ON public.kinra_v2_organization_staff FOR DELETE TO authenticated USING(public.kinra_v2_kinra_org_role(organization_id)='owner');
CREATE POLICY "Kinra v2: Owner reads invitations" ON public.kinra_v2_organization_invites FOR SELECT TO authenticated USING(public.kinra_v2_kinra_org_role(organization_id)='owner');
CREATE POLICY "Kinra v2: Owner creates invitations" ON public.kinra_v2_organization_invites FOR INSERT TO authenticated WITH CHECK(public.kinra_v2_kinra_org_role(organization_id)='owner');
CREATE POLICY "Kinra v2: Owner revokes invitations" ON public.kinra_v2_organization_invites FOR UPDATE TO authenticated USING(public.kinra_v2_kinra_org_role(organization_id)='owner') WITH CHECK(public.kinra_v2_kinra_org_role(organization_id)='owner');
CREATE POLICY "Kinra v2: Organization membership roster" ON public.kinra_v2_organization_memberships FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.kinra_v2_kinra_org_role(organization_id) IS NOT NULL);
CREATE POLICY "Kinra v2: Manager records membership" ON public.kinra_v2_organization_memberships FOR INSERT TO authenticated WITH CHECK(public.kinra_v2_kinra_org_role(organization_id) IN ('owner','manager'));
CREATE POLICY "Kinra v2: Manager updates membership" ON public.kinra_v2_organization_memberships FOR UPDATE TO authenticated USING(public.kinra_v2_kinra_org_role(organization_id) IN ('owner','manager')) WITH CHECK(public.kinra_v2_kinra_org_role(organization_id) IN ('owner','manager'));
CREATE POLICY "Kinra v2: Manager reads membership finance" ON public.kinra_v2_organization_membership_finance FOR SELECT TO authenticated USING(public.kinra_v2_kinra_org_role(organization_id) IN ('owner','manager'));
CREATE POLICY "Kinra v2: Manager records membership finance" ON public.kinra_v2_organization_membership_finance FOR INSERT TO authenticated WITH CHECK(public.kinra_v2_kinra_org_role(organization_id) IN ('owner','manager'));
CREATE POLICY "Kinra v2: Manager updates membership finance" ON public.kinra_v2_organization_membership_finance FOR UPDATE TO authenticated USING(public.kinra_v2_kinra_org_role(organization_id) IN ('owner','manager')) WITH CHECK(public.kinra_v2_kinra_org_role(organization_id) IN ('owner','manager'));
CREATE POLICY "Kinra v2: Staff sees organization and joined roster only" ON public.kinra_v2_feature_records FOR SELECT TO authenticated USING(
 kind='organization' AND public.kinra_v2_kinra_org_role(id) IS NOT NULL OR
 kind IN ('organization_member','membership_plan') AND public.kinra_v2_kinra_org_role((payload->>'organization_id')::uuid) IS NOT NULL
);

CREATE FUNCTION public.kinra_v2_kinra_guard_membership() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.kinra_v2_feature_records WHERE kind='organization_member' AND owner_id=NEW.user_id AND payload->>'organization_id'=NEW.organization_id::text) THEN RAISE EXCEPTION 'The person must join this organization first.' USING ERRCODE='23514'; END IF;
 IF NEW.plan_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.kinra_v2_feature_records WHERE id=NEW.plan_id AND kind='membership_plan' AND payload->>'organization_id'=NEW.organization_id::text) THEN RAISE EXCEPTION 'Choose a plan from this organization.' USING ERRCODE='23514'; END IF;
 NEW.updated_at:=now(); RETURN NEW;
END $$;
CREATE TRIGGER guard_organization_membership BEFORE INSERT OR UPDATE ON public.kinra_v2_organization_memberships FOR EACH ROW EXECUTE FUNCTION public.kinra_v2_kinra_guard_membership();

-- Narrow display-name projection: no full profile rows, contact details or
-- health fields become visible to an organization through roster membership.
CREATE FUNCTION public.kinra_v2_kinra_org_name(org_id uuid, person_id uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT p.display_name FROM public.kinra_v2_profiles p WHERE p.id=person_id AND public.kinra_v2_kinra_org_role(org_id) IS NOT NULL AND (
 EXISTS(SELECT 1 FROM public.kinra_v2_organization_staff WHERE organization_id=org_id AND user_id=person_id) OR
 EXISTS(SELECT 1 FROM public.kinra_v2_feature_records WHERE kind='organization_member' AND owner_id=person_id AND payload->>'organization_id'=org_id::text))
$$;

-- Only redemption can INSERT staff. The unguessable bearer code is shown for
-- review first; acceptance is atomic, signed-in, expires and is single-use.
CREATE FUNCTION public.kinra_v2_kinra_org_redeem(invitation_code uuid, accept boolean, expected_owner uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid:=auth.uid(); invitation public.kinra_v2_organization_invites; org public.kinra_v2_feature_records;
BEGIN
 IF actor IS NULL OR actor IS DISTINCT FROM expected_owner OR accept IS NULL THEN RAISE EXCEPTION 'Your account changed. Reopen this screen.' USING ERRCODE='42501'; END IF;
 SELECT * INTO invitation FROM public.kinra_v2_organization_invites WHERE code=invitation_code FOR UPDATE;
 SELECT * INTO org FROM public.kinra_v2_feature_records WHERE id=invitation.organization_id AND kind='organization';
 IF invitation.code IS NULL OR org.id IS NULL OR invitation.revoked_at IS NOT NULL OR invitation.expires_at<=now() OR invitation.used_at IS NOT NULL AND invitation.used_by IS DISTINCT FROM actor THEN RAISE EXCEPTION 'This invitation is unavailable or expired.' USING ERRCODE='42501'; END IF;
 IF org.owner_id=actor THEN RAISE EXCEPTION 'The owner already manages this organization.' USING ERRCODE='22023'; END IF;
 IF invitation.used_at IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.kinra_v2_organization_staff WHERE organization_id=org.id AND user_id=actor) THEN RAISE EXCEPTION 'This invitation has already been used.' USING ERRCODE='42501'; END IF;
 IF accept AND invitation.used_at IS NULL THEN
  IF EXISTS(SELECT 1 FROM public.kinra_v2_organization_staff WHERE organization_id=org.id AND user_id=actor) THEN RAISE EXCEPTION 'You already have a staff role. Ask the owner to change it.' USING ERRCODE='22023'; END IF;
  INSERT INTO public.kinra_v2_organization_staff(organization_id,user_id,role) VALUES(org.id,actor,invitation.role);
  UPDATE public.kinra_v2_organization_invites SET used_at=now(),used_by=actor WHERE code=invitation_code;
 END IF;
 RETURN jsonb_build_object('organizationId',org.id,'title',org.payload->>'name','role',invitation.role,'expiresAt',invitation.expires_at,'accepted',accept OR invitation.used_at IS NOT NULL);
END $$;

CREATE FUNCTION public.kinra_v2_kinra_org_admin(action text, org_id uuid, data jsonb, expected_owner uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE actor uuid:=auth.uid(); authority text; result jsonb; affected integer;
BEGIN
 IF actor IS NULL OR actor IS DISTINCT FROM expected_owner THEN RAISE EXCEPTION 'Your account changed. Reopen this screen.' USING ERRCODE='42501'; END IF;
 IF action='personalMemberships' THEN
  SELECT coalesce(jsonb_agg(jsonb_build_object('organizationId',m.organization_id,'userId',m.user_id,'status',m.status,'startDate',m.start_date,'endDate',m.end_date,'planId',m.plan_id) ORDER BY m.updated_at),'[]'::jsonb) INTO result FROM public.kinra_v2_organization_memberships m WHERE m.user_id=actor; RETURN result;
 END IF;
 IF action='list' THEN
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',o.id,'title',o.payload->>'name','city',o.payload->>'city','role',public.kinra_v2_kinra_org_role(o.id)) ORDER BY o.created_at),'[]'::jsonb) INTO result FROM public.kinra_v2_feature_records o WHERE o.kind='organization' AND public.kinra_v2_kinra_org_role(o.id) IS NOT NULL; RETURN result;
 END IF;
 authority:=public.kinra_v2_kinra_org_role(org_id);
 IF authority IS NULL THEN RAISE EXCEPTION 'Organization staff access required.' USING ERRCODE='42501'; END IF;
 IF action='staff' THEN
  SELECT coalesce(jsonb_agg(jsonb_build_object('organizationId',s.organization_id,'userId',s.user_id,'displayName',public.kinra_v2_kinra_org_name(s.organization_id,s.user_id),'role',s.role,'createdAt',s.created_at) ORDER BY s.created_at),'[]'::jsonb) INTO result FROM public.kinra_v2_organization_staff s WHERE s.organization_id=org_id; RETURN result;
 ELSIF action='members' THEN
  SELECT coalesce(jsonb_agg(jsonb_build_object('organizationId',m.payload->>'organization_id','userId',m.owner_id,'displayName',public.kinra_v2_kinra_org_name(org_id,m.owner_id),'joinedAt',m.created_at,'membership',CASE WHEN b.user_id IS NULL THEN NULL ELSE jsonb_build_object('organizationId',b.organization_id,'userId',b.user_id,'status',b.status,'startDate',b.start_date,'endDate',b.end_date,'planId',b.plan_id,'paidAmount',f.paid_amount,'currency',f.currency,'notes',coalesce(f.notes,'')) END) ORDER BY m.created_at),'[]'::jsonb) INTO result
  FROM public.kinra_v2_feature_records m LEFT JOIN public.kinra_v2_organization_memberships b ON b.organization_id=org_id AND b.user_id=m.owner_id LEFT JOIN public.kinra_v2_organization_membership_finance f ON f.organization_id=b.organization_id AND f.user_id=b.user_id WHERE m.kind='organization_member' AND m.payload->>'organization_id'=org_id::text; RETURN result;
 ELSIF action='saveMembership' THEN
  IF authority NOT IN ('owner','manager') THEN RAISE EXCEPTION 'A manager must review membership changes.' USING ERRCODE='42501'; END IF;
  INSERT INTO public.kinra_v2_organization_memberships(organization_id,user_id,status,start_date,end_date,plan_id) VALUES(org_id,(data->>'userId')::uuid,data->>'status',(data->>'startDate')::date,(data->>'endDate')::date,(data->>'planId')::uuid)
  ON CONFLICT(organization_id,user_id) DO UPDATE SET status=excluded.status,start_date=excluded.start_date,end_date=excluded.end_date,plan_id=excluded.plan_id;
  INSERT INTO public.kinra_v2_organization_membership_finance(organization_id,user_id,paid_amount,currency,notes) VALUES(org_id,(data->>'userId')::uuid,(data->>'paidAmount')::numeric,data->>'currency',coalesce(data->>'notes',''))
  ON CONFLICT(organization_id,user_id) DO UPDATE SET paid_amount=excluded.paid_amount,currency=excluded.currency,notes=excluded.notes;
  RETURN 'null'::jsonb;
 END IF;
 IF authority<>'owner' THEN RAISE EXCEPTION 'Only the organization owner manages staff invitations.' USING ERRCODE='42501'; END IF;
 IF action='createInvite' THEN
  INSERT INTO public.kinra_v2_organization_invites(organization_id,role,expires_at) VALUES(org_id,data->>'role',(data->>'expiresAt')::timestamptz) RETURNING jsonb_build_object('code',code,'organizationId',kinra_v2_organization_invites.organization_id,'role',role,'expiresAt',expires_at,'revokedAt',revoked_at,'usedAt',used_at,'usedBy',used_by) INTO result; RETURN result;
 ELSIF action='invites' THEN
  SELECT coalesce(jsonb_agg(jsonb_build_object('code',code,'organizationId',i.organization_id,'role',role,'expiresAt',expires_at,'revokedAt',revoked_at,'usedAt',used_at,'usedBy',used_by) ORDER BY created_at DESC),'[]'::jsonb) INTO result FROM public.kinra_v2_organization_invites i WHERE i.organization_id=org_id; RETURN result;
 ELSIF action='revokeInvite' THEN UPDATE public.kinra_v2_organization_invites i SET revoked_at=now() WHERE i.code=(data->>'code')::uuid AND i.organization_id=org_id;
 ELSIF action='removeStaff' THEN DELETE FROM public.kinra_v2_organization_staff s WHERE s.organization_id=org_id AND s.user_id=(data->>'userId')::uuid;
 ELSIF action='setStaffRole' THEN UPDATE public.kinra_v2_organization_staff s SET role=data->>'role' WHERE s.organization_id=org_id AND s.user_id=(data->>'userId')::uuid;
 ELSE RAISE EXCEPTION 'Unsupported organization action.' USING ERRCODE='22023'; END IF;
 GET DIAGNOSTICS affected=ROW_COUNT;
 IF affected=0 THEN RAISE EXCEPTION 'This organization record is no longer available.' USING ERRCODE='22023'; END IF;
 RETURN 'null'::jsonb;
END $$;

CREATE FUNCTION public.kinra_v2_kinra_valid_availability(p jsonb) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path='' AS $$
DECLARE r jsonb; seen text[]:='{}';
BEGIN
 IF p IS NULL OR jsonb_typeof(p)<>'object' OR NOT(p ?& ARRAY['timezone','published','rules','exceptions']) OR p - ARRAY['timezone','published','rules','exceptions'] <> '{}'::jsonb OR jsonb_typeof(p->'published')<>'boolean' OR NOT EXISTS(SELECT 1 FROM pg_catalog.pg_timezone_names WHERE name=p->>'timezone') OR jsonb_typeof(p->'rules')<>'array' OR jsonb_array_length(p->'rules')>28 OR jsonb_typeof(p->'exceptions')<>'array' OR jsonb_array_length(p->'exceptions')>100 THEN RETURN false; END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(p->'rules') LOOP
  IF r - ARRAY['weekday','start','end','slotMinutes'] <> '{}'::jsonb OR jsonb_typeof(r->'weekday')<>'number' OR jsonb_typeof(r->'slotMinutes')<>'number' OR (r->>'weekday')!~'^[0-6]$' OR (r->>'start')!~'^([01][0-9]|2[0-3]):[0-5][0-9]$' OR (r->>'end')!~'^([01][0-9]|2[0-3]):[0-5][0-9]$' OR (r->>'slotMinutes')!~'^[0-9]+$' OR (r->>'slotMinutes')::integer NOT BETWEEN 10 AND 240 OR r->>'end'<=r->>'start' OR NOT (r ?& ARRAY['weekday','start','end','slotMinutes']) THEN RETURN false; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p->'rules') a JOIN jsonb_array_elements(p->'rules') b ON a.value<b.value AND a.value->>'weekday'=b.value->>'weekday' AND a.value->>'start'<b.value->>'end' AND a.value->>'end'>b.value->>'start') THEN RETURN false; END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(p->'rules'))<>(SELECT count(DISTINCT value) FROM jsonb_array_elements(p->'rules')) THEN RETURN false; END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(p->'exceptions') LOOP
  IF r - ARRAY['date','unavailable','start','end','slotMinutes'] <> '{}'::jsonb OR NOT(r ?& ARRAY['date','unavailable']) OR (r->>'date')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR (r->>'date')::date::text<>r->>'date' OR jsonb_typeof(r->'unavailable')<>'boolean' OR r->>'date'=ANY(seen) THEN RETURN false; END IF;
  seen:=array_append(seen,r->>'date');
  IF NOT (r->>'unavailable')::boolean AND (NOT(r ?& ARRAY['start','end','slotMinutes']) OR (r->>'start')!~'^([01][0-9]|2[0-3]):[0-5][0-9]$' OR (r->>'end')!~'^([01][0-9]|2[0-3]):[0-5][0-9]$' OR r->>'end'<=r->>'start' OR (r->>'slotMinutes')!~'^[0-9]+$' OR (r->>'slotMinutes')::int NOT BETWEEN 10 AND 240) THEN RETURN false; END IF;
 END LOOP;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;
CREATE TABLE public.kinra_v2_coach_availability (
 coach_id uuid PRIMARY KEY DEFAULT auth.uid() REFERENCES public.kinra_v2_profiles(id) ON DELETE CASCADE,
 payload jsonb NOT NULL CHECK(coalesce(public.kinra_v2_kinra_valid_availability(payload),false))
);
ALTER TABLE public.kinra_v2_coach_availability ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.kinra_v2_coach_availability FROM PUBLIC,anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.kinra_v2_coach_availability TO authenticated;
GRANT ALL ON public.kinra_v2_coach_availability TO service_role;
CREATE POLICY "Kinra v2: Published schedule has no client information" ON public.kinra_v2_coach_availability FOR SELECT TO authenticated USING(coach_id=auth.uid() OR (payload->>'published')::boolean);
CREATE POLICY "Kinra v2: Coach publishes own availability" ON public.kinra_v2_coach_availability FOR INSERT TO authenticated WITH CHECK(coach_id=auth.uid() AND public.kinra_v2_has_role(auth.uid(),'trainer'));
CREATE POLICY "Kinra v2: Coach changes own availability" ON public.kinra_v2_coach_availability FOR UPDATE TO authenticated USING(coach_id=auth.uid() AND public.kinra_v2_has_role(auth.uid(),'trainer')) WITH CHECK(coach_id=auth.uid() AND public.kinra_v2_has_role(auth.uid(),'trainer'));
CREATE POLICY "Kinra v2: Coach removes own availability" ON public.kinra_v2_coach_availability FOR DELETE TO authenticated USING(coach_id=auth.uid());
CREATE FUNCTION public.kinra_v2_kinra_availability(coach uuid, expected_owner uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE result jsonb;
BEGIN
 IF auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM expected_owner THEN RAISE EXCEPTION 'Your account changed. Reopen this screen.' USING ERRCODE='42501'; END IF;
 SELECT payload INTO result FROM public.kinra_v2_coach_availability WHERE coach_id=coach; RETURN result;
END $$;
CREATE FUNCTION public.kinra_v2_kinra_save_availability(data jsonb, expected_owner uuid) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
BEGIN
 IF auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM expected_owner THEN RAISE EXCEPTION 'Your account changed. Reopen this screen.' USING ERRCODE='42501'; END IF;
 INSERT INTO public.kinra_v2_coach_availability(coach_id,payload) VALUES(auth.uid(),data) ON CONFLICT(coach_id) DO UPDATE SET payload=excluded.payload;
END $$;

-- Pure slot generation. Each date exception replaces that day's recurring
-- hours. DST gaps/folds with a duration mismatch are skipped, never normalized
-- into a different-length appointment. Values are explicit UTC instants.
CREATE FUNCTION public.kinra_v2_kinra_schedule_slots(p jsonb, from_day date, to_day date) RETURNS TABLE(starts_at timestamptz,ends_at timestamptz) LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path='' AS $$
DECLARE day date; r jsonb; exception jsonb; begin_local timestamp; end_local timestamp; cursor_local timestamp; span interval; zone text:=p->>'timezone'; finish timestamptz; start_instant timestamptz;
BEGIN
 IF p IS NULL OR NOT coalesce((p->>'published')::boolean,false) THEN RETURN; END IF;
 IF from_day IS NULL OR to_day IS NULL OR to_day<from_day OR to_day-from_day>31 THEN RAISE EXCEPTION 'Choose a date range of at most 32 days.' USING ERRCODE='22023'; END IF;
 FOR day IN SELECT generate_series(from_day,to_day,interval '1 day')::date LOOP
  SELECT value INTO exception FROM jsonb_array_elements(p->'exceptions') WHERE value->>'date'=day::text;
  IF exception IS NOT NULL AND (exception->>'unavailable')::boolean THEN CONTINUE; END IF;
  FOR r IN SELECT value FROM jsonb_array_elements(CASE WHEN exception IS NOT NULL THEN jsonb_build_array(exception) ELSE p->'rules' END) WHERE exception IS NOT NULL OR (value->>'weekday')::int=extract(dow FROM day)::int LOOP
   begin_local:=day+(r->>'start')::time; end_local:=day+(r->>'end')::time; span:=make_interval(mins=>(r->>'slotMinutes')::int); cursor_local:=begin_local;
   WHILE cursor_local+span<=end_local LOOP
    start_instant:=cursor_local AT TIME ZONE zone; finish:=(cursor_local+span) AT TIME ZONE zone;
    IF start_instant AT TIME ZONE zone=cursor_local AND finish AT TIME ZONE zone=cursor_local+span AND finish-start_instant=span THEN starts_at:=start_instant; ends_at:=finish; RETURN NEXT; END IF;
    cursor_local:=cursor_local+span;
   END LOOP;
  END LOOP;
 END LOOP;
END $$;

-- Narrow free/busy definer: private appointment rows must be checked to avoid
-- leaking other clients' identities. Only free slot timestamps leave this RPC.
CREATE FUNCTION public.kinra_v2_kinra_available_slots(coach uuid, from_day date, to_day date, expected_owner uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE p jsonb; result jsonb;
BEGIN
 IF auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM expected_owner THEN RAISE EXCEPTION 'Your account changed. Reopen this screen.' USING ERRCODE='42501'; END IF;
 IF from_day IS NULL OR to_day IS NULL OR to_day<from_day OR to_day-from_day>31 THEN RAISE EXCEPTION 'Choose a date range of at most 32 days.' USING ERRCODE='22023'; END IF;
 SELECT payload INTO p FROM public.kinra_v2_coach_availability WHERE coach_id=coach AND (payload->>'published')::boolean;
 SELECT coalesce(jsonb_agg(jsonb_build_object('startsAt',s.starts_at,'endsAt',s.ends_at) ORDER BY s.starts_at),'[]'::jsonb) INTO result FROM public.kinra_v2_kinra_schedule_slots(p,from_day,to_day) s WHERE s.starts_at>now() AND NOT EXISTS(SELECT 1 FROM public.kinra_v2_feature_records a WHERE a.kind='appointment' AND a.payload->>'coach_id'=coach::text AND a.payload->>'status' IN ('requested','confirmed') AND (a.payload->>'starts_at')::timestamptz<s.ends_at AND (a.payload->>'ends_at')::timestamptz>s.starts_at);
 RETURN result;
END $$;

-- Narrow appointment guard extends the existing authenticated feature guard.
-- Existing appointments can be cancelled/confirmed after schedule edits. New
-- or rescheduled requests must exactly match published slots; pending requests
-- reserve their time too. A per-coach lock serializes concurrent requests.
CREATE FUNCTION public.kinra_v2_kinra_guard_appointment_slot() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE p jsonb; coach uuid; begins timestamptz; finishes timestamptz; local_day date; changed boolean;
BEGIN
 IF NEW.kind<>'appointment' OR NEW.payload->>'status'='cancelled' THEN RETURN NEW; END IF;
 changed:=TG_OP='INSERT';
 IF TG_OP='UPDATE' THEN changed:=NEW.payload->>'starts_at' IS DISTINCT FROM OLD.payload->>'starts_at' OR NEW.payload->>'ends_at' IS DISTINCT FROM OLD.payload->>'ends_at' OR OLD.payload->>'status'='cancelled'; END IF;
 coach:=(NEW.payload->>'coach_id')::uuid; begins:=(NEW.payload->>'starts_at')::timestamptz; finishes:=(NEW.payload->>'ends_at')::timestamptz;
 PERFORM pg_advisory_xact_lock(hashtextextended(coach::text,0));
 SELECT payload INTO p FROM public.kinra_v2_coach_availability WHERE coach_id=coach AND (payload->>'published')::boolean;
 IF p IS NULL THEN RETURN NEW; END IF;
 IF changed THEN
  local_day:=(begins AT TIME ZONE (p->>'timezone'))::date;
  IF begins<=now() OR NOT EXISTS(SELECT 1 FROM public.kinra_v2_kinra_schedule_slots(p,local_day,local_day) s WHERE s.starts_at=begins AND s.ends_at=finishes) THEN RAISE EXCEPTION 'Choose an available slot from the coach schedule.' USING ERRCODE='23514'; END IF;
 END IF;
 IF (changed OR NEW.payload->>'status'='confirmed') AND EXISTS(SELECT 1 FROM public.kinra_v2_feature_records a WHERE a.id<>NEW.id AND a.kind='appointment' AND a.payload->>'coach_id'=coach::text AND a.payload->>'status' IN ('requested','confirmed') AND (a.payload->>'starts_at')::timestamptz<finishes AND (a.payload->>'ends_at')::timestamptz>begins) THEN RAISE EXCEPTION 'This time is no longer available.' USING ERRCODE='23505'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER guard_published_appointment_slot BEFORE INSERT OR UPDATE ON public.kinra_v2_feature_records FOR EACH ROW EXECUTE FUNCTION public.kinra_v2_kinra_guard_appointment_slot();

REVOKE ALL ON FUNCTION public.kinra_v2_kinra_org_role(uuid),public.kinra_v2_kinra_org_name(uuid,uuid),public.kinra_v2_kinra_guard_membership(),public.kinra_v2_kinra_org_redeem(uuid,boolean,uuid),public.kinra_v2_kinra_org_admin(text,uuid,jsonb,uuid),public.kinra_v2_kinra_valid_availability(jsonb),public.kinra_v2_kinra_availability(uuid,uuid),public.kinra_v2_kinra_save_availability(jsonb,uuid),public.kinra_v2_kinra_schedule_slots(jsonb,date,date),public.kinra_v2_kinra_available_slots(uuid,date,date,uuid),public.kinra_v2_kinra_guard_appointment_slot() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.kinra_v2_kinra_org_role(uuid),public.kinra_v2_kinra_org_name(uuid,uuid),public.kinra_v2_kinra_org_redeem(uuid,boolean,uuid),public.kinra_v2_kinra_org_admin(text,uuid,jsonb,uuid),public.kinra_v2_kinra_valid_availability(jsonb),public.kinra_v2_kinra_availability(uuid,uuid),public.kinra_v2_kinra_save_availability(jsonb,uuid),public.kinra_v2_kinra_schedule_slots(jsonb,date,date),public.kinra_v2_kinra_available_slots(uuid,date,date,uuid) TO authenticated,service_role;


-- Source: 0017_private_communities.sql
-- Private group membership is deliberate. Workspace roles and organization
-- staff never imply community access. Existing self-joined public groups stay
-- valid; manual bearer invitations add private membership only after acceptance.
CREATE TABLE public.kinra_v2_community_members (
 group_id uuid NOT NULL REFERENCES public.kinra_v2_feature_records(id) ON DELETE CASCADE,
 user_id uuid NOT NULL REFERENCES public.kinra_v2_profiles(id) ON DELETE CASCADE,
 joined_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(group_id,user_id)
);
CREATE TABLE public.kinra_v2_community_moderators (
 group_id uuid NOT NULL REFERENCES public.kinra_v2_feature_records(id) ON DELETE CASCADE,
 user_id uuid NOT NULL REFERENCES public.kinra_v2_profiles(id) ON DELETE CASCADE,
 created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(group_id,user_id)
);
CREATE TABLE public.kinra_v2_community_invites (
 code uuid PRIMARY KEY DEFAULT gen_random_uuid(), group_id uuid NOT NULL REFERENCES public.kinra_v2_feature_records(id) ON DELETE CASCADE,
 created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL,
 revoked_at timestamptz, used_at timestamptz, used_by uuid REFERENCES public.kinra_v2_profiles(id) ON DELETE SET NULL,
 CHECK(expires_at>=created_at+interval '5 minutes' AND expires_at<=created_at+interval '30 days')
);
CREATE TABLE public.kinra_v2_community_removals (
 group_id uuid NOT NULL REFERENCES public.kinra_v2_feature_records(id) ON DELETE CASCADE,
 user_id uuid NOT NULL REFERENCES public.kinra_v2_profiles(id) ON DELETE CASCADE,
 created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(group_id,user_id)
);
ALTER TABLE public.kinra_v2_community_members ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.kinra_v2_community_moderators ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.kinra_v2_community_invites ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.kinra_v2_community_removals ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.kinra_v2_community_members,public.kinra_v2_community_moderators,public.kinra_v2_community_invites FROM PUBLIC,anon,authenticated;
GRANT SELECT,DELETE ON public.kinra_v2_community_members,public.kinra_v2_community_moderators TO authenticated;
GRANT INSERT(group_id,user_id) ON public.kinra_v2_community_members,public.kinra_v2_community_moderators TO authenticated;
GRANT SELECT ON public.kinra_v2_community_invites TO authenticated;
GRANT INSERT(group_id,expires_at) ON public.kinra_v2_community_invites TO authenticated;
GRANT UPDATE(revoked_at) ON public.kinra_v2_community_invites TO authenticated;
GRANT ALL ON public.kinra_v2_community_members,public.kinra_v2_community_moderators,public.kinra_v2_community_invites TO service_role;
REVOKE ALL ON public.kinra_v2_community_removals FROM PUBLIC,anon,authenticated;
GRANT SELECT,INSERT(group_id,user_id) ON public.kinra_v2_community_removals TO authenticated;
GRANT ALL ON public.kinra_v2_community_removals TO service_role;

-- Narrow caller-role projection avoids recursion and reveals no other account
-- attributes. Blocking a group's owner removes that group's shared audience.
CREATE FUNCTION public.kinra_v2_kinra_community_role(target_group uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT CASE WHEN g.owner_id=auth.uid() THEN 'owner'
  WHEN NOT EXISTS(SELECT 1 FROM public.kinra_v2_community_removals r WHERE r.group_id=g.id AND r.user_id=auth.uid()) AND (EXISTS(SELECT 1 FROM public.kinra_v2_community_members m WHERE m.group_id=g.id AND m.user_id=auth.uid()) OR EXISTS(SELECT 1 FROM public.kinra_v2_feature_records m WHERE m.kind='group_member' AND m.owner_id=auth.uid() AND m.payload->>'group_id'=g.id::text))
  THEN CASE WHEN EXISTS(SELECT 1 FROM public.kinra_v2_community_moderators m WHERE m.group_id=g.id AND m.user_id=auth.uid()) THEN 'moderator' ELSE 'member' END END
 FROM public.kinra_v2_feature_records g WHERE auth.uid() IS NOT NULL AND g.id=target_group AND g.kind='group' AND NOT public.kinra_v2_kinra_feature_blocked(g.owner_id)
$$;
CREATE OR REPLACE FUNCTION public.kinra_v2_kinra_group_visible(group_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.kinra_v2_feature_records g WHERE g.id=group_id AND g.kind='group' AND NOT public.kinra_v2_kinra_feature_blocked(g.owner_id) AND (g.visibility='public' OR public.kinra_v2_kinra_community_role(g.id) IS NOT NULL))
$$;
CREATE POLICY "Kinra v2: Members see private community content" ON public.kinra_v2_feature_records FOR SELECT TO authenticated USING(
 kind='group' AND public.kinra_v2_kinra_community_role(id) IS NOT NULL OR
 kind IN ('post','group_member') AND payload ? 'group_id' AND public.kinra_v2_kinra_community_role((payload->>'group_id')::uuid) IS NOT NULL AND NOT public.kinra_v2_kinra_feature_blocked(owner_id)
);
CREATE POLICY "Kinra v2: Community roster" ON public.kinra_v2_community_members FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.kinra_v2_kinra_community_role(group_id) IS NOT NULL);
CREATE POLICY "Kinra v2: Public self join" ON public.kinra_v2_community_members FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND NOT EXISTS(SELECT 1 FROM public.kinra_v2_community_removals r WHERE r.group_id=kinra_v2_community_members.group_id AND r.user_id=auth.uid()) AND EXISTS(SELECT 1 FROM public.kinra_v2_feature_records g WHERE g.id=group_id AND g.kind='group' AND g.visibility='public' AND NOT public.kinra_v2_kinra_feature_blocked(g.owner_id)));
CREATE POLICY "Kinra v2: Leave or remove regular community member" ON public.kinra_v2_community_members FOR DELETE TO authenticated USING(user_id=auth.uid() OR public.kinra_v2_kinra_community_role(group_id)='owner' OR public.kinra_v2_kinra_community_role(group_id)='moderator' AND NOT EXISTS(SELECT 1 FROM public.kinra_v2_community_moderators m WHERE m.group_id=kinra_v2_community_members.group_id AND m.user_id=kinra_v2_community_members.user_id));
CREATE POLICY "Kinra v2: Members see moderator roles" ON public.kinra_v2_community_moderators FOR SELECT TO authenticated USING(public.kinra_v2_kinra_community_role(group_id) IS NOT NULL);
CREATE POLICY "Kinra v2: Owner appoints moderator" ON public.kinra_v2_community_moderators FOR INSERT TO authenticated WITH CHECK(public.kinra_v2_kinra_community_role(group_id)='owner' AND (EXISTS(SELECT 1 FROM public.kinra_v2_community_members m WHERE m.group_id=kinra_v2_community_moderators.group_id AND m.user_id=kinra_v2_community_moderators.user_id) OR EXISTS(SELECT 1 FROM public.kinra_v2_feature_records m WHERE m.kind='group_member' AND m.owner_id=kinra_v2_community_moderators.user_id AND m.payload->>'group_id'=kinra_v2_community_moderators.group_id::text)));
CREATE POLICY "Kinra v2: Owner removes moderator or moderator leaves" ON public.kinra_v2_community_moderators FOR DELETE TO authenticated USING(user_id=auth.uid() OR public.kinra_v2_kinra_community_role(group_id)='owner');
CREATE POLICY "Kinra v2: Moderators read group invitations" ON public.kinra_v2_community_invites FOR SELECT TO authenticated USING(public.kinra_v2_kinra_community_role(group_id) IN ('owner','moderator'));
CREATE POLICY "Kinra v2: Moderators create group invitations" ON public.kinra_v2_community_invites FOR INSERT TO authenticated WITH CHECK(public.kinra_v2_kinra_community_role(group_id) IN ('owner','moderator'));
CREATE POLICY "Kinra v2: Moderators revoke group invitations" ON public.kinra_v2_community_invites FOR UPDATE TO authenticated USING(public.kinra_v2_kinra_community_role(group_id) IN ('owner','moderator')) WITH CHECK(public.kinra_v2_kinra_community_role(group_id) IN ('owner','moderator'));
CREATE POLICY "Kinra v2: Removal history is scoped" ON public.kinra_v2_community_removals FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.kinra_v2_kinra_community_role(group_id) IN ('owner','moderator'));
CREATE POLICY "Kinra v2: Moderators remove regular members" ON public.kinra_v2_community_removals FOR INSERT TO authenticated WITH CHECK(
 user_id<>auth.uid() AND EXISTS(SELECT 1 FROM public.kinra_v2_feature_records g WHERE g.id=group_id AND g.kind='group' AND g.owner_id<>kinra_v2_community_removals.user_id) AND (public.kinra_v2_kinra_community_role(group_id)='owner' OR public.kinra_v2_kinra_community_role(group_id)='moderator' AND NOT EXISTS(SELECT 1 FROM public.kinra_v2_community_moderators m WHERE m.group_id=kinra_v2_community_removals.group_id AND m.user_id=kinra_v2_community_removals.user_id))
);
CREATE POLICY "Kinra v2: Moderators remove member posts" ON public.kinra_v2_feature_records FOR DELETE TO authenticated USING(kind='post' AND payload ? 'group_id' AND public.kinra_v2_kinra_community_role((payload->>'group_id')::uuid) IN ('owner','moderator'));
CREATE POLICY "Kinra v2: Moderators remove legacy group memberships" ON public.kinra_v2_feature_records FOR DELETE TO authenticated USING(kind='group_member' AND payload ? 'group_id' AND (public.kinra_v2_kinra_community_role((payload->>'group_id')::uuid)='owner' OR public.kinra_v2_kinra_community_role((payload->>'group_id')::uuid)='moderator' AND NOT EXISTS(SELECT 1 FROM public.kinra_v2_community_moderators m WHERE m.group_id=(payload->>'group_id')::uuid AND m.user_id=kinra_v2_feature_records.owner_id)));

-- Feature reactions/reports must recognize private group content too, while
-- maintaining the original ownership, published and assigned-plan audiences.
CREATE OR REPLACE FUNCTION public.kinra_v2_kinra_feature_visible(record_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.kinra_v2_feature_records r WHERE r.id=record_id AND (
 r.owner_id=auth.uid() OR
 r.kind='group' AND public.kinra_v2_kinra_community_role(r.id) IS NOT NULL OR
 r.kind='post' AND r.payload ? 'group_id' AND public.kinra_v2_kinra_community_role((r.payload->>'group_id')::uuid) IS NOT NULL AND NOT public.kinra_v2_kinra_feature_blocked(r.owner_id) OR
 r.visibility='public' AND NOT public.kinra_v2_kinra_feature_blocked(r.owner_id) AND (r.kind<>'post' OR NOT r.payload ? 'group_id' OR public.kinra_v2_kinra_group_visible((r.payload->>'group_id')::uuid)) OR
 r.client_id=auth.uid() AND EXISTS(SELECT 1 FROM public.kinra_v2_trainer_clients c WHERE c.client_id=r.client_id AND c.trainer_id=r.owner_id)))
$$;

-- This invoker trigger checks only caller-visible group membership. It rejects
-- moving a post between group/personal audiences and direct stale-member edits.
CREATE FUNCTION public.kinra_v2_kinra_guard_community_post() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE parent public.kinra_v2_feature_records;
BEGIN
 IF NEW.kind='group_member' AND EXISTS(SELECT 1 FROM public.kinra_v2_community_removals r WHERE r.group_id=(NEW.payload->>'group_id')::uuid AND r.user_id=NEW.owner_id) THEN RAISE EXCEPTION 'A moderator must issue a new invitation before you can rejoin.' USING ERRCODE='42501'; END IF;
 IF NEW.kind<>'post' THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND NEW.payload->>'group_id' IS DISTINCT FROM OLD.payload->>'group_id' THEN RAISE EXCEPTION 'A post cannot be moved to another audience.' USING ERRCODE='23514'; END IF;
 IF NEW.payload ? 'group_id' THEN
  SELECT * INTO parent FROM public.kinra_v2_feature_records WHERE id=(NEW.payload->>'group_id')::uuid AND kind='group';
  IF parent.id IS NULL OR public.kinra_v2_kinra_community_role(parent.id) IS NULL THEN RAISE EXCEPTION 'Join this group before posting.' USING ERRCODE='42501'; END IF;
  IF parent.visibility='private' AND NEW.visibility<>'private' THEN RAISE EXCEPTION 'Private group posts must remain private.' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $$;
-- This runs before the original feature guard; that guard is supplemented below
-- with private memberships through a narrow membership compatibility helper.
CREATE TRIGGER guard_community_post BEFORE INSERT OR UPDATE ON public.kinra_v2_feature_records FOR EACH ROW EXECUTE FUNCTION public.kinra_v2_kinra_guard_community_post();

-- The original guard only recognizes legacy group_member feature rows. Replace
-- that one condition with the role helper so accepted private memberships work
-- too. Fail explicitly if its reviewed source changed; no guard is bypassed and
-- no caller-controlled session setting acts as authorization.
DO $replace_guard$
DECLARE definition text;
BEGIN
 SELECT pg_get_functiondef('public.kinra_v2_kinra_guard_feature()'::regprocedure) INTO definition;
 definition:=replace(definition,
  'IF NEW.kind=''post'' AND parent.owner_id<>NEW.owner_id AND NOT EXISTS(SELECT 1 FROM kinra_v2_feature_records m WHERE m.kind=''group_member'' AND m.owner_id=NEW.owner_id AND m.payload->>''group_id''=parent.id::text) THEN',
  'IF NEW.kind=''post'' AND public.kinra_v2_kinra_community_role(parent.id) IS NULL THEN');
 IF definition=pg_get_functiondef('public.kinra_v2_kinra_guard_feature()'::regprocedure) THEN RAISE EXCEPTION 'The community guard requires the reviewed feature guard version.'; END IF;
 EXECUTE definition;
END $replace_guard$;

-- Names are the only profile projection exposed to an authorized group roster.
CREATE FUNCTION public.kinra_v2_kinra_community_name(target_group uuid,person_id uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT p.display_name FROM public.kinra_v2_profiles p WHERE p.id=person_id AND public.kinra_v2_kinra_community_role(target_group) IS NOT NULL AND (
 EXISTS(SELECT 1 FROM public.kinra_v2_feature_records g WHERE g.id=target_group AND g.kind='group' AND g.owner_id=person_id) OR
 EXISTS(SELECT 1 FROM public.kinra_v2_community_members m WHERE m.group_id=target_group AND m.user_id=person_id) OR
 EXISTS(SELECT 1 FROM public.kinra_v2_feature_records m WHERE m.kind='group_member' AND m.owner_id=person_id AND m.payload->>'group_id'=target_group::text))
$$;

-- Single-use invitation acceptance must read a secret bearer row and add a
-- private membership; the narrowly scoped definer is necessary for that atomic
-- transition. No raw invitation lookup is granted to its recipient.
CREATE FUNCTION public.kinra_v2_kinra_community_redeem(invitation_code uuid,accept boolean,expected_owner uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid:=auth.uid(); invitation public.kinra_v2_community_invites; community public.kinra_v2_feature_records;
BEGIN
 IF actor IS NULL OR actor IS DISTINCT FROM expected_owner OR accept IS NULL THEN RAISE EXCEPTION 'Your account changed. Reopen this screen.' USING ERRCODE='42501'; END IF;
 SELECT * INTO invitation FROM public.kinra_v2_community_invites WHERE code=invitation_code FOR UPDATE;
 SELECT * INTO community FROM public.kinra_v2_feature_records WHERE id=invitation.group_id AND kind='group';
 IF invitation.code IS NULL OR community.id IS NULL OR public.kinra_v2_kinra_feature_blocked(community.owner_id) OR invitation.revoked_at IS NOT NULL OR invitation.expires_at<=now() OR invitation.used_at IS NOT NULL AND invitation.used_by IS DISTINCT FROM actor OR EXISTS(SELECT 1 FROM public.kinra_v2_community_removals r WHERE r.group_id=community.id AND r.user_id=actor AND r.created_at>=invitation.created_at) THEN RAISE EXCEPTION 'This invitation is unavailable or expired.' USING ERRCODE='42501'; END IF;
 IF invitation.used_at IS NOT NULL AND public.kinra_v2_kinra_community_role(community.id) IS NULL THEN RAISE EXCEPTION 'This invitation has already been used.' USING ERRCODE='42501'; END IF;
 IF accept AND invitation.used_at IS NULL THEN
  DELETE FROM public.kinra_v2_community_removals WHERE group_id=community.id AND user_id=actor;
  INSERT INTO public.kinra_v2_community_members(group_id,user_id) VALUES(community.id,actor) ON CONFLICT DO NOTHING;
  UPDATE public.kinra_v2_community_invites SET used_at=now(),used_by=actor WHERE code=invitation_code;
 END IF;
 RETURN jsonb_build_object('groupId',community.id,'title',community.payload->>'title','visibility',community.visibility,'expiresAt',invitation.expires_at,'accepted',accept OR invitation.used_at IS NOT NULL);
END $$;

CREATE FUNCTION public.kinra_v2_kinra_community_admin(action text,group_id uuid,data jsonb,expected_owner uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE actor uuid:=auth.uid(); authority text; community public.kinra_v2_feature_records; result jsonb; target uuid; affected integer;
BEGIN
 IF actor IS NULL OR actor IS DISTINCT FROM expected_owner THEN RAISE EXCEPTION 'Your account changed. Reopen this screen.' USING ERRCODE='42501'; END IF;
 IF action='personalMemberships' THEN
  SELECT coalesce(jsonb_agg(jsonb_build_object('groupId',m.group_id,'userId',m.user_id,'joinedAt',m.joined_at) ORDER BY m.joined_at),'[]'::jsonb) INTO result FROM public.kinra_v2_community_members m WHERE m.user_id=actor; RETURN result;
 END IF;
 IF action='list' THEN
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',g.id,'title',g.payload->>'title','description',g.payload->>'description','type',g.payload->>'type','visibility',g.visibility,'role',public.kinra_v2_kinra_community_role(g.id)) ORDER BY g.created_at DESC),'[]'::jsonb) INTO result FROM public.kinra_v2_feature_records g WHERE g.kind='group'; RETURN result;
 END IF;
 SELECT * INTO community FROM public.kinra_v2_feature_records g WHERE g.id=kinra_v2_kinra_community_admin.group_id AND g.kind='group';
 IF community.id IS NULL THEN RAISE EXCEPTION 'This group is unavailable.' USING ERRCODE='42501'; END IF;
 authority:=public.kinra_v2_kinra_community_role(community.id);
 IF action='join' THEN
  IF community.visibility<>'public' THEN RAISE EXCEPTION 'Accept an invitation to join a private group.' USING ERRCODE='42501'; END IF;
  IF EXISTS(SELECT 1 FROM public.kinra_v2_community_removals r WHERE r.group_id=community.id AND r.user_id=actor) THEN RAISE EXCEPTION 'A moderator must issue a new invitation before you can rejoin.' USING ERRCODE='42501'; END IF;
  IF authority IS NULL THEN INSERT INTO public.kinra_v2_community_members(group_id,user_id) VALUES(community.id,actor) ON CONFLICT DO NOTHING; END IF; RETURN 'null'::jsonb;
 ELSIF action='removePost' THEN
  DELETE FROM public.kinra_v2_feature_records p WHERE p.id=(data->>'postId')::uuid AND p.kind='post' AND p.payload->>'group_id'=community.id::text AND (p.owner_id=actor OR authority IN ('owner','moderator'));
  GET DIAGNOSTICS affected=ROW_COUNT; IF affected=0 THEN RAISE EXCEPTION 'This post is unavailable or cannot be removed by you.' USING ERRCODE='42501'; END IF; RETURN 'null'::jsonb;
 END IF;
 IF authority IS NULL THEN RAISE EXCEPTION 'Join this group first.' USING ERRCODE='42501'; END IF;
 IF action='members' THEN
  SELECT coalesce(jsonb_agg(jsonb_build_object('userId',u.user_id,'displayName',public.kinra_v2_kinra_community_name(community.id,u.user_id),'role',CASE WHEN u.user_id=community.owner_id THEN 'owner' WHEN EXISTS(SELECT 1 FROM public.kinra_v2_community_moderators x WHERE x.group_id=community.id AND x.user_id=u.user_id) THEN 'moderator' ELSE 'member' END,'joinedAt',u.joined_at) ORDER BY u.joined_at),'[]'::jsonb) INTO result
  FROM (SELECT people.user_id,min(people.joined_at) joined_at FROM (SELECT community.owner_id user_id,community.created_at joined_at UNION ALL SELECT m.user_id,m.joined_at FROM public.kinra_v2_community_members m WHERE m.group_id=community.id UNION ALL SELECT m.owner_id,m.created_at FROM public.kinra_v2_feature_records m WHERE m.kind='group_member' AND m.payload->>'group_id'=community.id::text) people GROUP BY people.user_id) u; RETURN result;
 ELSIF action='leave' THEN
  IF authority='owner' THEN RAISE EXCEPTION 'The owner must delete the group instead of leaving it.' USING ERRCODE='22023'; END IF;
  DELETE FROM public.kinra_v2_community_moderators m WHERE m.group_id=community.id AND m.user_id=actor;
  DELETE FROM public.kinra_v2_community_members m WHERE m.group_id=community.id AND m.user_id=actor;
  DELETE FROM public.kinra_v2_feature_records m WHERE m.kind='group_member' AND m.owner_id=actor AND m.payload->>'group_id'=community.id::text;
  RETURN 'null'::jsonb;
 END IF;
 IF authority NOT IN ('owner','moderator') THEN RAISE EXCEPTION 'A group moderator must review this action.' USING ERRCODE='42501'; END IF;
 IF action='createInvite' THEN
  INSERT INTO public.kinra_v2_community_invites(group_id,expires_at) VALUES(community.id,(data->>'expiresAt')::timestamptz) RETURNING jsonb_build_object('code',code,'groupId',kinra_v2_community_invites.group_id,'expiresAt',expires_at,'revokedAt',revoked_at,'usedAt',used_at,'usedBy',used_by) INTO result; RETURN result;
 ELSIF action='invites' THEN
  SELECT coalesce(jsonb_agg(jsonb_build_object('code',code,'groupId',i.group_id,'expiresAt',expires_at,'revokedAt',revoked_at,'usedAt',used_at,'usedBy',used_by) ORDER BY created_at DESC),'[]'::jsonb) INTO result FROM public.kinra_v2_community_invites i WHERE i.group_id=community.id; RETURN result;
 ELSIF action='revokeInvite' THEN
  UPDATE public.kinra_v2_community_invites i SET revoked_at=now() WHERE i.group_id=community.id AND i.code=(data->>'code')::uuid; RETURN 'null'::jsonb;
 ELSIF action='setModerator' THEN
  IF authority<>'owner' OR NOT(data ? 'enabled') OR data->>'enabled' NOT IN ('true','false') OR NOT EXISTS(SELECT 1 FROM public.kinra_v2_community_members m WHERE m.group_id=community.id AND m.user_id=(data->>'userId')::uuid UNION ALL SELECT 1 FROM public.kinra_v2_feature_records m WHERE m.kind='group_member' AND m.owner_id=(data->>'userId')::uuid AND m.payload->>'group_id'=community.id::text) THEN RAISE EXCEPTION 'Only the owner can change an existing member moderator role.' USING ERRCODE='42501'; END IF;
  IF (data->>'enabled')::boolean THEN INSERT INTO public.kinra_v2_community_moderators(group_id,user_id) VALUES(community.id,(data->>'userId')::uuid) ON CONFLICT DO NOTHING; ELSE DELETE FROM public.kinra_v2_community_moderators m WHERE m.group_id=community.id AND m.user_id=(data->>'userId')::uuid; END IF; RETURN 'null'::jsonb;
 ELSIF action='kick' THEN
  target:=(data->>'userId')::uuid;
  IF target=community.owner_id OR target=actor OR authority='moderator' AND EXISTS(SELECT 1 FROM public.kinra_v2_community_moderators m WHERE m.group_id=community.id AND m.user_id=target) THEN RAISE EXCEPTION 'A moderator cannot remove the owner or another moderator. Use Leave for yourself.' USING ERRCODE='42501'; END IF;
  INSERT INTO public.kinra_v2_community_removals(group_id,user_id) VALUES(community.id,target) ON CONFLICT DO NOTHING;
  DELETE FROM public.kinra_v2_community_moderators m WHERE m.group_id=community.id AND m.user_id=target;
  DELETE FROM public.kinra_v2_community_members m WHERE m.group_id=community.id AND m.user_id=target;
  DELETE FROM public.kinra_v2_feature_records m WHERE m.kind='group_member' AND m.owner_id=target AND m.payload->>'group_id'=community.id::text;
  RETURN 'null'::jsonb;
 END IF;
 RAISE EXCEPTION 'Unsupported community action.' USING ERRCODE='22023';
END $$;
REVOKE ALL ON FUNCTION public.kinra_v2_kinra_community_role(uuid),public.kinra_v2_kinra_community_name(uuid,uuid),public.kinra_v2_kinra_guard_community_post(),public.kinra_v2_kinra_community_redeem(uuid,boolean,uuid),public.kinra_v2_kinra_community_admin(text,uuid,jsonb,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.kinra_v2_kinra_community_role(uuid),public.kinra_v2_kinra_community_name(uuid,uuid),public.kinra_v2_kinra_community_redeem(uuid,boolean,uuid),public.kinra_v2_kinra_community_admin(text,uuid,jsonb,uuid) TO authenticated,service_role;


-- Source: 0018_message_attachments.sql
-- Private uploads remain tied to a live coach/client conversation. Uploading a
-- file alone never makes it readable by the other participant.
CREATE OR REPLACE FUNCTION public.kinra_v2_kinra_send_message(recipient_id uuid,body text,expected_owner uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid:=auth.uid(); trainer uuid; client uuid; message_id uuid;
BEGIN
  IF actor IS NULL OR actor IS DISTINCT FROM expected_owner OR recipient_id IS NULL OR body IS NULL OR length(trim(body)) NOT BETWEEN 1 AND 10000 THEN RAISE EXCEPTION 'Matching account and a message are required' USING ERRCODE='42501'; END IF;
  IF public.kinra_v2_kinra_feature_blocked(recipient_id) THEN RAISE EXCEPTION 'This conversation is unavailable' USING ERRCODE='42501'; END IF;
  SELECT c.trainer_id,c.client_id INTO trainer,client FROM public.kinra_v2_trainer_clients c WHERE c.trainer_id=actor AND c.client_id=recipient_id OR c.trainer_id=recipient_id AND c.client_id=actor;
  IF trainer IS NULL THEN RAISE EXCEPTION 'Choose a connected coach or client' USING ERRCODE='42501'; END IF;
  INSERT INTO public.kinra_v2_trainer_notes(trainer_id,client_id,sender_id,body,shared,kind) VALUES(trainer,client,actor,trim(body),true,'text') RETURNING id INTO message_id;
  RETURN message_id;
END $$;
CREATE TABLE public.kinra_v2_message_attachments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  message_id uuid NOT NULL UNIQUE REFERENCES public.kinra_v2_trainer_notes(id) ON DELETE CASCADE,
  owner_id uuid NOT NULL REFERENCES public.kinra_v2_profiles(id) ON DELETE CASCADE,
  recipient_id uuid NOT NULL REFERENCES public.kinra_v2_profiles(id) ON DELETE CASCADE,
  storage_path text NOT NULL UNIQUE,
  filename text NOT NULL CHECK(length(filename) BETWEEN 1 AND 200),
  mime text NOT NULL CHECK(mime IN ('image/jpeg','image/png','image/webp','application/pdf')),
  bytes bigint NOT NULL CHECK(bytes BETWEEN 1 AND 10485760),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX kinra_v2_message_attachment_recipient ON public.kinra_v2_message_attachments(recipient_id);
CREATE INDEX kinra_v2_message_attachment_owner ON public.kinra_v2_message_attachments(owner_id);
ALTER TABLE public.kinra_v2_message_attachments ENABLE ROW LEVEL SECURITY;
GRANT SELECT ON public.kinra_v2_message_attachments TO authenticated;
GRANT ALL ON public.kinra_v2_message_attachments TO service_role;
REVOKE ALL ON public.kinra_v2_message_attachments FROM anon;
CREATE POLICY "Kinra v2: Participants read connected attachments" ON public.kinra_v2_message_attachments FOR SELECT TO authenticated USING (
  (auth.uid()=owner_id OR auth.uid()=recipient_id) AND EXISTS(SELECT 1 FROM public.kinra_v2_trainer_clients c WHERE c.trainer_id=owner_id AND c.client_id=recipient_id OR c.trainer_id=recipient_id AND c.client_id=owner_id)
);
INSERT INTO storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
VALUES('kinra-v2-message-attachments','kinra-v2-message-attachments',false,10485760,ARRAY['image/jpeg','image/png','image/webp','application/pdf']);
CREATE POLICY "Kinra v2: Upload own conversation file" ON storage.objects FOR INSERT TO authenticated WITH CHECK (
  bucket_id='kinra-v2-message-attachments' AND (storage.foldername(name))[1]=auth.uid()::text
);
CREATE POLICY "Kinra v2: Read own or connected message file" ON storage.objects FOR SELECT TO authenticated USING (
  bucket_id='kinra-v2-message-attachments' AND ((storage.foldername(name))[1]=auth.uid()::text OR EXISTS(SELECT 1 FROM public.kinra_v2_message_attachments a WHERE a.storage_path=name))
);
CREATE POLICY "Kinra v2: Delete own conversation file" ON storage.objects FOR DELETE TO authenticated USING (
  bucket_id='kinra-v2-message-attachments' AND (storage.foldername(name))[1]=auth.uid()::text
);
CREATE FUNCTION public.kinra_v2_kinra_send_attachment(recipient uuid,body text,path text,filename text,mime text,bytes bigint,expected_owner uuid) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid:=auth.uid(); message uuid;
BEGIN
  IF actor IS NULL OR actor IS DISTINCT FROM expected_owner OR recipient=actor OR
     path !~ ('^'||actor::text||'/[0-9a-f-]{36}\.(jpg|png|webp|pdf)$') OR
     length(filename) NOT BETWEEN 1 AND 200 OR filename ~ '[\x00-\x1f\x7f/\\]' OR
     mime NOT IN ('image/jpeg','image/png','image/webp','application/pdf') OR bytes NOT BETWEEN 1 AND 10485760 OR length(trim(body)) NOT BETWEEN 1 AND 10000
  THEN RAISE EXCEPTION 'Invalid attachment or account' USING ERRCODE='42501'; END IF;
  IF public.kinra_v2_kinra_feature_blocked(recipient) THEN RAISE EXCEPTION 'This conversation is unavailable' USING ERRCODE='42501'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.kinra_v2_trainer_clients c WHERE c.trainer_id=actor AND c.client_id=recipient OR c.trainer_id=recipient AND c.client_id=actor) THEN RAISE EXCEPTION 'Choose a connected coach or client' USING ERRCODE='42501'; END IF;
  -- Storage metadata is authoritative for the uploaded size and MIME type.
  IF NOT EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='kinra-v2-message-attachments' AND o.name=path
    AND o.metadata->>'mimetype'=mime AND (o.metadata->>'size')::bigint=bytes)
  THEN RAISE EXCEPTION 'Upload the selected file before sending' USING ERRCODE='23514'; END IF;
  -- A retry uses the same uploaded path and returns the original message.
  SELECT a.message_id INTO message FROM public.kinra_v2_message_attachments a WHERE a.storage_path=path AND a.owner_id=actor AND a.recipient_id=recipient;
  IF message IS NOT NULL THEN RETURN message; END IF;
  message:=public.kinra_v2_kinra_send_message(recipient,body,actor);
  INSERT INTO public.kinra_v2_message_attachments(message_id,owner_id,recipient_id,storage_path,filename,mime,bytes)
  VALUES(message,actor,recipient,path,filename,mime,bytes);
  RETURN message;
END $$;
REVOKE ALL ON FUNCTION public.kinra_v2_kinra_send_attachment(uuid,text,text,text,text,bigint,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.kinra_v2_kinra_send_attachment(uuid,text,text,text,text,bigint,uuid) TO authenticated,service_role;


-- Source: 0019_device_reminders.sql
CREATE TABLE public.kinra_v2_device_subscriptions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid() REFERENCES public.kinra_v2_profiles(id) ON DELETE CASCADE,
  endpoint text NOT NULL UNIQUE CHECK(length(endpoint)<=3000 AND endpoint ~ '^https://(fcm\.googleapis\.com|updates\.push\.services\.mozilla\.com|web\.push\.apple\.com|[a-z0-9.-]+\.notify\.windows\.com)/[^[:space:]]+$'),
  p256dh text NOT NULL CHECK(p256dh ~ '^[A-Za-z0-9_-]{87}$'),
  auth_key text NOT NULL CHECK(auth_key ~ '^[A-Za-z0-9_-]{22}$'),
  locale text NOT NULL CHECK(locale IN ('en','bs','de')), created_at timestamptz NOT NULL DEFAULT now(), last_test_at timestamptz
);
CREATE INDEX kinra_v2_device_subscription_owner ON public.kinra_v2_device_subscriptions(owner_id);
ALTER TABLE public.kinra_v2_device_subscriptions ENABLE ROW LEVEL SECURITY;
GRANT SELECT,INSERT,DELETE ON public.kinra_v2_device_subscriptions TO authenticated;
GRANT UPDATE(last_test_at) ON public.kinra_v2_device_subscriptions TO authenticated;
GRANT ALL ON public.kinra_v2_device_subscriptions TO service_role;
CREATE POLICY "Kinra v2: Own notification devices" ON public.kinra_v2_device_subscriptions TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE FUNCTION public.kinra_v2_kinra_claim_push_test(subscription_endpoint text,expected_owner uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE device public.kinra_v2_device_subscriptions;
BEGIN
  IF auth.uid() IS NULL OR auth.uid() IS DISTINCT FROM expected_owner THEN RAISE EXCEPTION 'Matching account required' USING ERRCODE='42501'; END IF;
  UPDATE public.kinra_v2_device_subscriptions d SET last_test_at=now() WHERE d.owner_id=auth.uid() AND d.endpoint=subscription_endpoint AND (d.last_test_at IS NULL OR d.last_test_at<now()-interval '1 minute') RETURNING d.* INTO device;
  IF device.id IS NULL THEN RAISE EXCEPTION 'Enable this device and wait one minute between tests' USING ERRCODE='23514'; END IF;
  RETURN jsonb_build_object('endpoint',device.endpoint,'p256dh',device.p256dh,'auth_key',device.auth_key,'locale',device.locale);
END $$;
REVOKE ALL ON FUNCTION public.kinra_v2_kinra_claim_push_test(text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.kinra_v2_kinra_claim_push_test(text,uuid) TO authenticated,service_role;
CREATE TABLE public.kinra_v2_push_dispatch_config (singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton), token_hash bytea NOT NULL);
ALTER TABLE public.kinra_v2_push_dispatch_config ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.kinra_v2_push_dispatch_config FROM PUBLIC,anon,authenticated;
CREATE TABLE public.kinra_v2_push_deliveries (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), subscription_id uuid NOT NULL REFERENCES public.kinra_v2_device_subscriptions(id) ON DELETE CASCADE,
  reminder_id uuid NOT NULL REFERENCES public.kinra_v2_feature_records(id) ON DELETE CASCADE, local_date date NOT NULL,
  status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sent','failed')), attempts int NOT NULL DEFAULT 0,
  lease_until timestamptz, sent_at timestamptz, error_code int,
  UNIQUE(subscription_id,reminder_id,local_date)
);
CREATE INDEX kinra_v2_push_delivery_reminder ON public.kinra_v2_push_deliveries(reminder_id);
ALTER TABLE public.kinra_v2_push_deliveries ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.kinra_v2_push_deliveries FROM PUBLIC,anon,authenticated;
-- Narrow dispatcher capability, unrelated to the Supabase service-role key.
-- Only a hash is stored here. The actual token lives in deployment secrets.
CREATE FUNCTION public.kinra_v2_kinra_push_authorized(token text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
  SELECT length(token)>=40 AND EXISTS(SELECT 1 FROM public.kinra_v2_push_dispatch_config c WHERE c.token_hash=sha256(convert_to(token,'UTF8')))
$$;
CREATE FUNCTION public.kinra_v2_kinra_push_clock(zone text) RETURNS timestamp LANGUAGE sql STABLE SET search_path='' AS $$
  SELECT now() AT TIME ZONE coalesce((SELECT name FROM pg_catalog.pg_timezone_names WHERE name=zone),'UTC')
$$;
CREATE FUNCTION public.kinra_v2_kinra_push_due(token text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE result jsonb;
BEGIN
  IF public.kinra_v2_kinra_push_authorized(token) IS DISTINCT FROM true THEN RAISE EXCEPTION 'Dispatcher authorization required' USING ERRCODE='42501'; END IF;
  -- Local timestamps are calculated by PostgreSQL's timezone database, including
  -- DST. A short catch-up window tolerates scheduler delays without old alerts.
  INSERT INTO public.kinra_v2_push_deliveries(subscription_id,reminder_id,local_date)
  SELECT d.id,r.id,(public.kinra_v2_kinra_push_clock(r.payload->>'timezone'))::date
  FROM public.kinra_v2_device_subscriptions d JOIN public.kinra_v2_feature_records r ON r.owner_id=d.owner_id AND r.kind='reminder'
  LEFT JOIN public.kinra_v2_feature_records p ON p.owner_id=d.owner_id AND p.kind='notification_preferences'
  WHERE r.payload->>'enabled'='true'
    AND coalesce((p.payload->'categories'->>'reminders')::boolean,true)
    AND extract(dow FROM public.kinra_v2_kinra_push_clock(r.payload->>'timezone'))::int IN (SELECT v::int FROM jsonb_array_elements_text(r.payload->'weekdays') v)
    AND (public.kinra_v2_kinra_push_clock(r.payload->>'timezone')) - ((public.kinra_v2_kinra_push_clock(r.payload->>'timezone'))::date+(r.payload->>'time')::time) BETWEEN interval '0 minutes' AND interval '10 minutes'
    AND (p.id IS NULL OR p.payload->>'quiet_start'=p.payload->>'quiet_end' OR NOT (
      CASE WHEN p.payload->>'quiet_start'<p.payload->>'quiet_end' THEN
        (public.kinra_v2_kinra_push_clock(p.payload->>'timezone'))::time >= (p.payload->>'quiet_start')::time AND (public.kinra_v2_kinra_push_clock(p.payload->>'timezone'))::time < (p.payload->>'quiet_end')::time
      ELSE (public.kinra_v2_kinra_push_clock(p.payload->>'timezone'))::time >= (p.payload->>'quiet_start')::time OR (public.kinra_v2_kinra_push_clock(p.payload->>'timezone'))::time < (p.payload->>'quiet_end')::time END))
  ON CONFLICT DO NOTHING;
  -- Re-check opt-out and quiet hours for pending retries as well.
  WITH candidates AS (
    SELECT q.id FROM public.kinra_v2_push_deliveries q JOIN public.kinra_v2_device_subscriptions d ON d.id=q.subscription_id
    JOIN public.kinra_v2_feature_records r ON r.id=q.reminder_id
    LEFT JOIN public.kinra_v2_feature_records p ON p.owner_id=d.owner_id AND p.kind='notification_preferences'
    WHERE q.status='pending' AND q.attempts<3 AND (q.lease_until IS NULL OR q.lease_until<now())
      AND r.payload->>'enabled'='true' AND coalesce((p.payload->'categories'->>'reminders')::boolean,true)
      AND q.local_date=(public.kinra_v2_kinra_push_clock(r.payload->>'timezone'))::date
      AND (public.kinra_v2_kinra_push_clock(r.payload->>'timezone')) - (q.local_date+(r.payload->>'time')::time) BETWEEN interval '0 minutes' AND interval '10 minutes'
      AND (p.id IS NULL OR p.payload->>'quiet_start'=p.payload->>'quiet_end' OR NOT (
        CASE WHEN p.payload->>'quiet_start'<p.payload->>'quiet_end' THEN
          (public.kinra_v2_kinra_push_clock(p.payload->>'timezone'))::time >= (p.payload->>'quiet_start')::time AND (public.kinra_v2_kinra_push_clock(p.payload->>'timezone'))::time < (p.payload->>'quiet_end')::time
        ELSE (public.kinra_v2_kinra_push_clock(p.payload->>'timezone'))::time >= (p.payload->>'quiet_start')::time OR (public.kinra_v2_kinra_push_clock(p.payload->>'timezone'))::time < (p.payload->>'quiet_end')::time END))
    ORDER BY q.id LIMIT 100 FOR UPDATE OF q SKIP LOCKED
  ), claimed AS (
    UPDATE public.kinra_v2_push_deliveries q SET lease_until=now()+interval '2 minutes',attempts=attempts+1
    FROM candidates c WHERE q.id=c.id RETURNING q.*
  ) SELECT coalesce(jsonb_agg(jsonb_build_object('deliveryId',q.id,'subscription',jsonb_build_object('endpoint',d.endpoint,'keys',jsonb_build_object('p256dh',d.p256dh,'auth',d.auth_key)),'locale',d.locale)),'[]'::jsonb)
  INTO result FROM claimed q JOIN public.kinra_v2_device_subscriptions d ON d.id=q.subscription_id;
  DELETE FROM public.kinra_v2_push_deliveries q WHERE q.local_date<current_date-30;
  RETURN result;
END $$;
CREATE FUNCTION public.kinra_v2_kinra_push_ack(token text,delivery uuid,code int) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
BEGIN
  IF public.kinra_v2_kinra_push_authorized(token) IS DISTINCT FROM true THEN RAISE EXCEPTION 'Dispatcher authorization required' USING ERRCODE='42501'; END IF;
  IF code IN (404,410) THEN
    DELETE FROM public.kinra_v2_device_subscriptions d USING public.kinra_v2_push_deliveries q WHERE q.id=delivery AND q.subscription_id=d.id;
  ELSE
    UPDATE public.kinra_v2_push_deliveries q SET status=CASE WHEN code BETWEEN 200 AND 299 THEN 'sent' WHEN attempts>=3 OR code BETWEEN 400 AND 499 AND code<>429 THEN 'failed' ELSE 'pending' END,
      sent_at=CASE WHEN code BETWEEN 200 AND 299 THEN now() ELSE NULL END,error_code=code WHERE q.id=delivery;
  END IF;
END $$;
REVOKE ALL ON FUNCTION public.kinra_v2_kinra_push_authorized(text),public.kinra_v2_kinra_push_due(text),public.kinra_v2_kinra_push_ack(text,uuid,int) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.kinra_v2_kinra_push_due(text),public.kinra_v2_kinra_push_ack(text,uuid,int) TO anon,service_role;


-- Source: 0020_onboarding_workspaces.sql
-- Five onboarding paths share the same private profile and original role.
-- Additional optional questionnaire answers remain owner-only.
CREATE OR REPLACE FUNCTION public.kinra_v2_kinra_valid_onboarding(v jsonb) RETURNS boolean LANGUAGE plpgsql STABLE SET search_path='' AS $$
BEGIN
  IF jsonb_typeof(v) IS DISTINCT FROM 'object' OR NOT (v ?& ARRAY['role','display_name','goal','first_action','theme','language','timezone']) THEN RETURN false; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(v) k WHERE k NOT IN ('role','display_name','goal','first_action','theme','language','timezone','gender','height_cm','weight_kg','units','experience','birth_date','activity_level','city','limitations','workspace')) THEN RETURN false; END IF;
  IF jsonb_typeof(v->'display_name') IS DISTINCT FROM 'string' OR length(v->>'display_name')>80 OR jsonb_typeof(v->'goal') IS DISTINCT FROM 'string' OR length(v->>'goal')>160 THEN RETURN false; END IF;
  IF jsonb_typeof(v->'theme') IS DISTINCT FROM 'string' OR v->>'theme' NOT IN ('dark','light','system') OR jsonb_typeof(v->'language') IS DISTINCT FROM 'string' OR v->>'language' NOT IN ('en','bs','de') THEN RETURN false; END IF;
  IF jsonb_typeof(v->'timezone') IS DISTINCT FROM 'string' OR (v->>'timezone') !~ '^[A-Za-z0-9_+/-]{1,80}$' THEN RETURN false; END IF;
  IF v->'role' <> 'null'::jsonb AND (jsonb_typeof(v->'role') <> 'string' OR v->>'role' NOT IN ('solo','client','trainer')) THEN RETURN false; END IF;
  IF v->'first_action' <> 'null'::jsonb AND (jsonb_typeof(v->'first_action') <> 'string' OR v->>'first_action' NOT IN ('workout','food','sleep','connect','plan','overview','program','clients','dashboard','organization','membership','community')) THEN RETURN false; END IF;
  IF v->>'first_action' IS NOT NULL AND NOT coalesce(CASE WHEN v->>'workspace'='organization' THEN v->>'first_action' IN ('organization','membership','community') ELSE CASE v->>'role' WHEN 'solo' THEN v->>'first_action' IN ('workout','food','sleep') WHEN 'client' THEN v->>'first_action' IN ('connect','plan','overview') WHEN 'trainer' THEN v->>'first_action' IN ('program','clients','dashboard') ELSE false END END,false) THEN RETURN false; END IF;
  IF v ? 'gender' AND v->'gender' <> 'null'::jsonb AND (jsonb_typeof(v->'gender') <> 'string' OR v->>'gender' NOT IN ('woman','man','non_binary','another_identity','prefer_not_to_say')) THEN RETURN false; END IF;
  IF v ? 'experience' AND v->'experience' <> 'null'::jsonb AND (jsonb_typeof(v->'experience') <> 'string' OR v->>'experience' NOT IN ('new','some','experienced')) THEN RETURN false; END IF;
  IF v ? 'units' AND (jsonb_typeof(v->'units') IS DISTINCT FROM 'string' OR v->>'units' NOT IN ('metric','imperial')) THEN RETURN false; END IF;
  IF v ? 'height_cm' AND v->'height_cm' <> 'null'::jsonb THEN
    IF jsonb_typeof(v->'height_cm') <> 'number' THEN RETURN false; END IF;
    IF (v->>'height_cm')::numeric NOT BETWEEN 80 AND 250 THEN RETURN false; END IF;
  END IF;
  IF v ? 'weight_kg' AND v->'weight_kg' <> 'null'::jsonb THEN
    IF jsonb_typeof(v->'weight_kg') <> 'number' THEN RETURN false; END IF;
    IF (v->>'weight_kg')::numeric NOT BETWEEN 20 AND 350 THEN RETURN false; END IF;
  END IF;

  IF v ? 'birth_date' AND v->'birth_date' <> 'null'::jsonb THEN
    IF jsonb_typeof(v->'birth_date') <> 'string' OR v->>'birth_date' !~ '^\d{4}-\d{2}-\d{2}$' THEN RETURN false; END IF;
    BEGIN IF (v->>'birth_date')::date < DATE '1900-01-01' OR (v->>'birth_date')::date > CURRENT_DATE THEN RETURN false; END IF;
    EXCEPTION WHEN datetime_field_overflow OR invalid_datetime_format THEN RETURN false; END;
  END IF;
  IF v ? 'activity_level' AND v->'activity_level' <> 'null'::jsonb AND (jsonb_typeof(v->'activity_level') <> 'string' OR v->>'activity_level' NOT IN ('low','moderate','high')) THEN RETURN false; END IF;
  IF v ? 'city' AND (jsonb_typeof(v->'city') IS DISTINCT FROM 'string' OR length(v->>'city')>100) THEN RETURN false; END IF;
  IF v ? 'limitations' AND (jsonb_typeof(v->'limitations') IS DISTINCT FROM 'string' OR length(v->>'limitations')>1000) THEN RETURN false; END IF;
  IF v ? 'workspace' AND v->'workspace'<>'null'::jsonb THEN
    IF jsonb_typeof(v->'workspace')<>'string' OR v->>'workspace' NOT IN ('solo','client','trainer','specialist','organization') THEN RETURN false; END IF;
    IF v->>'role' IS NOT NULL AND (CASE v->>'workspace' WHEN 'specialist' THEN 'trainer' WHEN 'organization' THEN 'solo' ELSE v->>'workspace' END) IS DISTINCT FROM v->>'role' THEN RETURN false; END IF;
  END IF;
  RETURN true;
END $$;


CREATE OR REPLACE FUNCTION public.kinra_v2_kinra_save_onboarding(data jsonb,stage integer,finish boolean,expected_owner uuid) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE actor uuid:=auth.uid(); chosen public.kinra_v2_app_role; existing public.kinra_v2_app_role; prior jsonb; modern boolean; next_stage integer; merged jsonb;
BEGIN
  IF actor IS NULL OR actor IS DISTINCT FROM expected_owner THEN RAISE EXCEPTION 'Your account changed. Reopen this screen before saving.' USING ERRCODE='42501'; END IF;
  modern := data ? 'height_cm';
  IF stage IS NULL OR finish IS NULL OR stage NOT BETWEEN 0 AND (CASE WHEN modern THEN 4 ELSE 3 END) OR NOT public.kinra_v2_kinra_valid_onboarding(data) THEN RAISE EXCEPTION 'Enter valid setup details.' USING ERRCODE='22023'; END IF;
  IF finish AND (nullif(trim(data->>'display_name'),'') IS NULL OR data->>'role' IS NULL OR data->>'first_action' IS NULL) THEN RAISE EXCEPTION 'Complete the required setup steps.' USING ERRCODE='22023'; END IF;
  INSERT INTO public.kinra_v2_profiles(id) VALUES(actor) ON CONFLICT(id) DO NOTHING;
  INSERT INTO public.kinra_v2_onboarding_state(owner_id,answers,step) VALUES(actor,data,stage) ON CONFLICT(owner_id) DO NOTHING;
  SELECT answers INTO prior FROM public.kinra_v2_onboarding_state WHERE owner_id=actor FOR UPDATE;
  SELECT role INTO existing FROM public.kinra_v2_user_roles WHERE user_id=actor;
  IF existing IS NOT NULL AND existing::text IS DISTINCT FROM data->>'role' THEN RAISE EXCEPTION 'Your account type is already set. Reopen setup to continue.' USING ERRCODE='22023'; END IF;
  -- A cached four-step client must not erase facts saved by the new setup.
  merged := coalesce(prior,'{}'::jsonb) || data;
  next_stage := CASE WHEN NOT modern AND stage>=2 THEN stage+1 ELSE stage END;
  IF finish THEN
    chosen:=(data->>'role')::public.kinra_v2_app_role;
    INSERT INTO public.kinra_v2_user_roles(user_id,role) VALUES(actor,chosen) ON CONFLICT(user_id) DO NOTHING;
    IF NOT EXISTS(SELECT 1 FROM public.kinra_v2_user_roles WHERE user_id=actor AND role=chosen) THEN RAISE EXCEPTION 'Your account type is already set. Reopen setup to continue.' USING ERRCODE='22023'; END IF;
    -- Only initial completion selects a workspace. Retaking setup cannot
    -- unexpectedly switch the current account context or grant staff access.
    IF existing IS NULL THEN
      INSERT INTO public.kinra_v2_account_roles(owner_id,role) VALUES(actor,chosen::text) ON CONFLICT DO NOTHING;
      INSERT INTO public.kinra_v2_account_roles(owner_id,role) VALUES(actor,coalesce(data->>'workspace',chosen::text)) ON CONFLICT DO NOTHING;
      INSERT INTO public.kinra_v2_account_context(owner_id,active_role) VALUES(actor,coalesce(data->>'workspace',chosen::text)) ON CONFLICT(owner_id) DO NOTHING;
    END IF;
    UPDATE public.kinra_v2_profiles SET display_name=trim(data->>'display_name'),goal=nullif(trim(data->>'goal'),'') WHERE id=actor;
    INSERT INTO public.kinra_v2_feature_records(owner_id,kind,payload) VALUES(actor,'preferences',jsonb_build_object('language',data->>'language','theme',data->>'theme','modules','{}'::jsonb,'timezone',data->>'timezone') || CASE WHEN data ? 'units' THEN jsonb_build_object('units',data->>'units') ELSE '{}'::jsonb END)
      ON CONFLICT(owner_id,kind,dedupe_key) DO UPDATE SET payload=public.kinra_v2_feature_records.payload || jsonb_build_object('language',data->>'language','theme',data->>'theme') || CASE WHEN data ? 'units' THEN jsonb_build_object('units',data->>'units') ELSE '{}'::jsonb END;
  END IF;
  UPDATE public.kinra_v2_onboarding_state SET answers=merged,version=2,step=CASE WHEN finish THEN 4 ELSE next_stage END,updated_at=now(),completed_at=CASE WHEN finish THEN coalesce(completed_at,now()) ELSE NULL END WHERE owner_id=actor;
END $$;
